(function(root){root.GLCPrestigeData={"version":1,"dice":["d4","d6","d8","d10","d12","d20","d20+d4","d20+d6","d20+d8","d20+d10","d20+d12","d20+d20"],"stages":["I","II","III","IV","V","Saikyō"],"paths":[{"id":"striker-atletica","role":"Combattente","style":"Striker","skill":"Atletica","talents":["potenza-del-titano","impatto-devastante","raffica-senza-fine"]},{"id":"striker-acrobazia","role":"Combattente","style":"Striker","skill":"Acrobazia","talents":["precisione-assoluta","raffica-senza-fine"]},{"id":"swordsman","role":"Combattente","style":"Swordsman","skill":"Atletica","talents":["fendente-sovrano","taglio-colossale","guardia-invalicabile","maestria-assoluta-della-lama"]},{"id":"crusher","role":"Combattente","style":"Crusher","skill":"Atletica","talents":["maglio-inarrestabile","onda-sismica","guardia-frantumata","arresto-del-colosso"]},{"id":"sniper","role":"Combattente","style":"Sniper","skill":"Osservazione","talents":["tiro-risolutivo","precisione-chirurgica","interdizione-sovrana","danza-dei-proiettili"]},{"id":"capitano","role":"Capitano","style":"Capitano","skill":"Comunicazione","talents":["ordine-sovrano","grido-leggendario","il-piano-perfetto"]},{"id":"musicista","role":"Musicista","style":"Musicista","skill":"Arte","talents":["orchestra-vivente","risonanza-leggendaria","requiem-sovrano"]},{"id":"tossicologo","role":"Dottore","style":"Tossicologo","skill":"Medicina","talents":["tossine-sovrane","nebbia-pestilenziale","antidoto-perfetto"]},{"id":"infermeria","role":"Dottore","style":"Infermeria","skill":"Medicina","talents":["chirurgia-leggendaria","intervento-prodigioso","diagnosi-assoluta"]},{"id":"chimico","role":"Dottore","style":"Chimico","skill":"Medicina","talents":["reazioni-catastrofiche","sintesi-perfetta","dispersione-sovrana"]},{"id":"inventore","role":"Ingegnere","style":"Inventore","skill":"Meccanica","talents":["progettazione-perfetta","arsenale-da-campo","sovraccarico-controllato"]},{"id":"meccanico","role":"Ingegnere","style":"Meccanico","skill":"Meccanica","talents":["regia-meccanica","ricostruzione-prodigiosa","dominio-delle-macchine"]},{"id":"carpentiere","role":"Ingegnere","style":"Carpentiere","skill":"Carpenteria","talents":["ricostruzione-leggendaria","nave-leggendaria","scafo-inespugnabile"]},{"id":"navigatore","role":"Navigatore","style":"Navigatore","skill":"Navigazione","talents":["timoniere-leggendario","rotta-sovrana","cartografia-leggendaria"]},{"id":"archeologo","role":"Archeologo","style":"Archeologo","skill":"Archeologia","talents":["lettura-assoluta","archivio-vivente","maestro-dei-meccanismi-antichi"]},{"id":"cuoco","role":"Cuoco","style":"Cuoco","skill":"Cucina","talents":["nutrimento-leggendario","servizio-sovrano","secondo-fuoco-leggendario"]}],"talents":[{"id":"potenza-del-titano","name":"Potenza del Titano","paths":["striker-atletica"],"requires":[],"replaces":[],"action":"passive","costST":0,"saikyoST":0,"match":"unarmed","uses":null,"saikyoUses":null,"resource":null,"source":"combattenti","start":157,"end":164,"anchor":"combattenti-potenza-del-titano","blocks":[{"type":"p","style":"Normal","text":"Tipo: passivo. Costo aggiuntivo: 0 ST. Applicazione: attacchi base a mani nude e Tecniche offensive dello Striker eseguite a mani nude."},{"type":"p","style":"Normal","text":"Quando un tuo attacco compatibile va a segno, tira una volta il tuo intero dado di Forza e somma il risultato al normale danno del colpo. Se Forza possiede un dado di Prestigio, tira entrambi i dadi e somma i risultati."},{"type":"p","style":"Normal","text":"Con Forza d20+d12, per esempio, il danno aggiuntivo è d20+d12. Questo beneficio si applica a ciascun colpo riuscito, compresi gli attacchi aggiuntivi concessi da Raffica Senza Fine e gli attacchi di Reazione compatibili."},{"type":"p","style":"Normal","text":"Il tiro di danno aggiuntivo è distinto dal tiro per colpire. Potenza del Titano non aggiunge una seconda volta il risultato della prova d’attacco e non modifica da sola portata, numero di bersagli o area del colpo. Si applicano le normali riduzioni del danno."},{"type":"p","style":"Normal","text":"Quando un’altra capacità utilizza il danno totale di questo colpo, comprende anche il contributo di Potenza del Titano. Quando una capacità richiede soltanto un tiro di Forza, come lo Schianto di Proiezione Colossale, non aggiungere nuovamente questo Talento."},{"type":"p","style":"Normal","text":"Esempio: una Tecnica infligge 12 danni prima di questo Talento. Con Forza d20+d8 ottieni 14 sul d20 e 5 sul d8: aggiungi 19 e il danno totale è 31, prima delle eventuali riduzioni."}],"frequency":"combat"},{"id":"impatto-devastante","name":"Onda Titanica","paths":["striker-atletica"],"requires":["Pugni che Rompono"],"replaces":["Pugni che Rompono"],"action":"bonus","costST":2,"saikyoST":2,"match":"unarmed","uses":1,"saikyoUses":1,"resource":null,"source":"combattenti","start":164,"end":176,"anchor":"combattenti-onda-titanica","blocks":[{"type":"p","style":"Normal","text":"Evoluzione di: Pugni che Rompono. Prerequisito: possedere Pugni che Rompono. Tipo: attivo. Attivazione: 1 Azione Bonus dopo un colpo riuscito. Costo aggiuntivo: 2 ST. Limite: 1 volta nel tuo turno. Per ampliare l’area: Forza deve aver raggiunto il Prestigio."},{"type":"p","style":"Normal","text":"Quando nel tuo turno un attacco a mani nude o una Tecnica offensiva in mischia dello Striker colpisce una creatura, un oggetto o una superficie, puoi spendere l’Azione Bonus e 2 ST per propagare l’impatto nell’area circostante. Il raggio massimo è quello del tuo Prestigio di Forza; puoi scegliere un raggio inferiore."},{"type":"p","style":"Normal","text":"Il Talento è l’attivazione necessaria per propagare il danno del colpo anche contro le creature. La sola scala ambientale resta disponibile senza il Talento e non consuma l’Azione Bonus o le 2 ST. Per usare Onda Titanica devi possedere il Talento, avere l’Azione Bonus e almeno 2 ST disponibili e aver messo a segno il colpo nel tuo turno. Un attacco mancato o annullato da una difesa non soddisfa la condizione. Non servono Proiezione o Schianto per questa onda."},{"type":"p","style":"Normal","text":"L’area ha origine nel punto colpito. L’onda d’urto investe le altre creature raggiunte dall’impatto, escluso chi lo ha generato. Eventuali alleati presenti nell’area devono difendersi normalmente. Il Talento non consente di escludere liberamente singole creature dall’area scelta."},{"type":"p","style":"Normal","text":"Onda Titanica è un’eccezione concessa dal Talento di Prestigio, non una Forma Area del Costruttore dello Striker. Lo Striker non possiede Tecniche Area ordinarie di Stile. L’onda nasce sempre dalla propagazione di un singolo colpo riuscito e segue esclusivamente il proprio raggio, condizioni e costi.","aggiunta":true},{"type":"p","style":"Normal","text":"Un’eventuale Area concessa da una Fonte speciale resta distinta e non moltiplica i punti d’origine né aumenta il raggio di Onda Titanica. Allo stesso modo, l’onda non aumenta né sostituisce la sagoma della Tecnica.","aggiunta":true},{"type":"p","style":"Normal","text":"Usa il risultato del tiro per colpire originario per risolvere l’impatto contro ciascuna creatura aggiuntiva, applicando Difesa Passiva, Difese Attive, Reazioni e coperture secondo le regole ordinarie. Se il colpo contro una superficie non richiedeva un tiro, effettua un unico normale tiro per colpire valido per l’area. Ogni creatura può quindi subire un esito diverso."},{"type":"p","style":"Normal","text":"Tira il danno del colpo iniziale una sola volta, includendo Potenza del Titano e gli altri bonus applicabili. Usa quel risultato come D e, per ciascun bersaglio aggiuntivo colpito, applica la frazione prevista dalla sua distanza dal punto d’impatto. Il bersaglio originario ha già ricevuto il colpo: non subisce una seconda copia dello stesso danno per il fatto di essere nell’area."},{"type":"p","style":"Normal","text":"Il danno propagato non comprende un eventuale Schianto successivo e gli effetti secondari rivolti al solo bersaglio iniziale non si estendono automaticamente a tutti. Le Tecniche e l’Haki conservano requisiti, costi e limiti propri."},{"type":"p","style":"Normal","text":"Pugni che Rompono è incorporato nell’evoluzione: i colpi a mani nude continuano a infliggere danno pieno agli oggetti compatibili. Il danno pieno elimina le penalità previste per colpire quegli oggetti a mani nude; l’attenuazione con la distanza dell’impatto continua ad applicarsi. Le strutture raggiunte dall’onda ricevono il danno della propria fascia e cedono secondo la loro resistenza e i loro PS. Questo beneficio non ignora automaticamente le riduzioni del danno delle creature."},{"type":"p","style":"Normal","text":"Esempio: con Forza d20+d10 puoi propagare un colpo fino a 100 m di raggio. Il colpo iniziale infligge 40 danni. Una creatura colpita a 20 m riceve 40 danni; a 40 m ne riceve 20; a 60 m ne riceve 10; a 90 m ne riceve 5, prima delle rispettive riduzioni. Il bersaglio iniziale riceve una sola applicazione di 40 danni."}],"frequency":"turn"},{"id":"precisione-assoluta","name":"Precisione Assoluta","paths":["striker-acrobazia"],"requires":[],"replaces":[],"action":"passive","costST":0,"saikyoST":0,"match":"precision","uses":null,"saikyoUses":null,"resource":null,"source":"combattenti","start":178,"end":194,"anchor":"combattenti-precisione-assoluta","blocks":[{"type":"p","style":"Normal","text":"Tipo: passivo. Costo aggiuntivo del Talento: 0 ST. Beneficio: permette di inserire Punto di Rottura nelle proprie Tecniche offensive in mischia dello Striker basate sull’Attributo Tecnica."},{"type":"p","style":"Normal","text":"Il Talento rende disponibile un effetto di precisione da scegliere nella costruzione della mossa. Per applicarlo, la Tecnica deve contenere effettivamente Punto di Rottura, possedere lo slot necessario e pagarne il costo. Precisione Assoluta non si applica automaticamente a ogni attacco base."},{"type":"p","style":"Heading 4","text":"Punto di Rottura"},{"type":"p","style":"Normal","text":"Famiglia: Controllo. Costo: 2 ST. Slot: 1 Effetto. Requisito: Precisione Assoluta e una Tecnica offensiva in mischia dello Striker basata sull’Attributo Tecnica. Condizione: colpo pulito, con margine almeno +4 secondo le regole ordinarie."},{"type":"p","style":"Normal","text":"Prima dell’attacco dichiara la parte o la funzione che vuoi neutralizzare. Il punto deve essere accessibile alla portata della Tecnica e coerente con l’anatomia del bersaglio o con il funzionamento dell’oggetto. Le difese, le coperture e le condizioni necessarie a colpire quel bersaglio continuano ad applicarsi."},{"type":"p","style":"Normal","text":"Paga il costo dell’effetto insieme agli altri costi della Tecnica, anche se l’attacco manca o non ottiene un colpo pulito. Se ottieni soltanto un colpo a segno, infliggi il normale danno senza applicare Punto di Rottura."},{"type":"p","style":"Normal","text":"Con un colpo pulito infliggi il normale danno della Tecnica e puoi sostituire lo Stordimento o lo Sbilanciamento della Firma con uno dei seguenti risultati."},{"type":"p","style":"List Bullet","text":"Mano: la mano colpita non può impugnare o utilizzare ciò che tiene. L’altra mano e le capacità che non dipendono dalla mano neutralizzata restano disponibili."},{"type":"p","style":"List Bullet","text":"Gamba: il bersaglio non può effettuare Movimento volontario finché non recupera la funzione. Può ancora attaccare o utilizzare capacità compatibili con la propria posizione."},{"type":"p","style":"List Bullet","text":"Presa: fai cedere una presa mantenuta con la parte colpita e liberi chi o ciò che quella presa tratteneva. Il bersaglio può tentare una nuova presa seguendo le regole ordinarie."},{"type":"p","style":"List Bullet","text":"Componente: danneggi un elemento accessibile, come il grilletto di un’arma, il timone, una giuntura o il meccanismo di un cannone. Si applica il danno della Tecnica a quel componente, valutandone resistenza e Punti Struttura propri quando presenti; il risultato dipende dal danno sufficiente a comprometterne la funzione."},{"type":"p","style":"Normal","text":"La limitazione su una mano o una gamba termina quando il bersaglio spende un’Azione principale per recuperare la funzione, oppure alla fine dello scontro. Rappresenta una neutralizzazione temporanea e non una mutilazione permanente. La presa interrotta è un risultato immediato; i danni a un componente seguono invece le regole degli oggetti e delle riparazioni."},{"type":"p","style":"Normal","text":"Puoi mantenere una sola funzione fisica neutralizzata per bersaglio con questo effetto. Una nuova applicazione su una parte diversa sostituisce la precedente; ripetere il colpo sulla stessa parte non somma ulteriori limitazioni."},{"type":"p","style":"Normal","text":"Punto di Rottura sostituisce soltanto lo stato della Firma per quel colpo e ne condivide il limite di una attivazione per turno. Applicare Punto di Rottura consuma l’unica attivazione della Firma; se Il Colpo Sfonda si è già attivato in quel turno, non puoi applicare nuovamente la Firma attraverso Punto di Rottura. Gli eventuali altri effetti della Tecnica seguono le proprie regole, rispettando il limite ordinario degli effetti per famiglia. Il Talento non permette di ignorare automaticamente una difesa o di colpire una parte fisicamente irraggiungibile."},{"type":"p","style":"Normal","text":"Esempio: dichiari di voler neutralizzare la mano con cui un nemico impugna una pistola. La Tecnica con Punto di Rottura costa 2 ST per questo effetto, oltre agli altri costi. Ottieni un colpo pulito: il nemico subisce il danno e la mano non può utilizzare la pistola. Può recuperare la funzione spendendo la sua Azione principale oppure proseguire lo scontro usando le capacità rimaste disponibili."}],"frequency":"combat"},{"id":"raffica-senza-fine","name":"Raffica Senza Fine","paths":["striker-atletica","striker-acrobazia"],"requires":["Raffica — Maestria"],"replaces":["Raffica — Base","Raffica — Migliorato","Raffica — Maestria"],"action":"bonus","costST":1,"saikyoST":1,"match":"unarmed","uses":1,"saikyoUses":1,"resource":null,"source":"combattenti","start":195,"end":216,"anchor":"combattenti-raffica-senza-fine","blocks":[{"type":"p","style":"Normal","text":"Raffica Senza Fine è un’opzione comune ai percorsi Forza e Atletica e Tecnica e Acrobazia. La sua acquisizione utilizza la Skill di Ruolo del rispettivo percorso e segue il normale numero di scelte di Prestigio disponibili."},{"type":"p","style":"Normal","text":"Evoluzione di: Raffica · Maestria. Tipo: attivo. Attivazione: 1 Azione Bonus dopo un attacco a mani nude. Limite: 1 attivazione nel tuo turno. Costo progressivo: 1 ST il primo attacco extra, 2 ST il secondo, 3 ST il terzo, 4 ST il quarto e così via, oltre a tutti i costi normali dell’eventuale Tecnica."},{"type":"p","style":"Normal","text":"Dopo aver effettuato un attacco a mani nude, puoi attivare Raffica Senza Fine per eseguire una sequenza di attacchi aggiuntivi nello stesso turno. L’attacco iniziale può essere un attacco base oppure una Tecnica offensiva in mischia dello Striker eseguita a mani nude e non deve necessariamente essere andato a segno."},{"type":"p","style":"Normal","text":"Il costo della Raffica cresce per ogni attacco aggiuntivo effettuato durante quella attivazione: il primo costa 1 ST, il secondo 2 ST, il terzo 3 ST, il quarto 4 ST, il quinto 5 ST e così via. Non esiste un numero massimo prestabilito di attacchi extra: il limite è la Stamina che il personaggio può e decide di spendere. Ogni attacco aggiuntivo può essere un attacco base a mani nude oppure una Tecnica offensiva in mischia dello Striker. Se scegli una Tecnica, paghi sempre sia il costo progressivo di Raffica relativo a quell’attacco sia tutti i costi normali della Tecnica e dei suoi effetti. I due costi si sommano integralmente."},{"type":"p","style":"Normal","text":"Decidi se proseguire dopo aver risolto ciascun attacco e paghi il costo del successivo prima di tentarlo. Un attacco mancato consuma normalmente la Stamina pagata ma non interrompe Raffica Senza Fine."},{"type":"p","style":"Normal","text":"Puoi concentrare gli attacchi sullo stesso avversario oppure distribuirli tra bersagli raggiungibili. Ogni attacco conserva la propria portata, il proprio tiro per colpire, il proprio danno e le normali possibilità di difesa del bersaglio. Raffica Senza Fine non concede Movimento gratuito o spostamenti speciali. Eventuali movimenti derivano dal Movimento ancora disponibile o dagli effetti contenuti nella Tecnica impiegata e ne consumano normalmente i costi e gli eventuali budget."},{"type":"p","style":"Normal","text":"Gli attacchi aggiuntivi non sono nuove Azioni principali e non concedono ulteriori Azioni Bonus. Non possono essere usati per attivare altri Talenti attivi, attivare l’Haki, eseguire Tecniche di Supporto o di Potenziamento oppure utilizzare liberamente una Special Move. Talenti passivi e potenziamenti compatibili possono applicarsi ai singoli colpi secondo le proprie regole, compresi Potenza del Titano e i potenziamenti degli Attributi Proiezione Colossale, Spostamento Fulmineo e Agilità Sovrumana. Ogni Tecnica deve contenere gli effetti necessari e rispettare i relativi requisiti."},{"type":"p","style":"Normal","text":"Questa evoluzione incorpora completamente la catena di Raffica. Nello stesso turno non puoi sommare o riattivare Raffica · Base, Migliorato o Maestria per ottenere attacchi aggiuntivi ulteriori. Il Colpo Sfonda rimane soggetto al limite generale di una sola attivazione per turno."},{"type":"p","style":"Heading 4","text":"Esempi di costo","aggiunta":true},{"type":"p","style":"List Bullet","text":"1° attacco extra base: Raffica 1 ST + Tecnica 0 ST = 1 ST.","aggiunta":true},{"type":"p","style":"List Bullet","text":"2° attacco extra base: Raffica 2 ST + Tecnica 0 ST = 2 ST.","aggiunta":true},{"type":"p","style":"List Bullet","text":"3° attacco extra base: Raffica 3 ST + Tecnica 0 ST = 3 ST.","aggiunta":true},{"type":"p","style":"List Bullet","text":"4° attacco extra base: Raffica 4 ST + Tecnica 0 ST = 4 ST.","aggiunta":true},{"type":"p","style":"List Bullet","text":"1° extra con Tecnica da 2 ST: Raffica 1 ST + Tecnica 2 ST = 3 ST.","aggiunta":true},{"type":"p","style":"List Bullet","text":"2° extra con Tecnica da 2 ST: Raffica 2 ST + Tecnica 2 ST = 4 ST.","aggiunta":true},{"type":"p","style":"List Bullet","text":"3° extra con Tecnica da 2 ST: Raffica 3 ST + Tecnica 2 ST = 5 ST.","aggiunta":true},{"type":"p","style":"List Bullet","text":"1° extra con Scatto: Raffica 1 ST + Scatto 1 ST = 2 ST, oltre agli altri eventuali costi della Tecnica.","aggiunta":true},{"type":"p","style":"List Bullet","text":"1° extra con Punto di Rottura: Raffica 1 ST + Punto di Rottura 2 ST = 3 ST, oltre agli altri eventuali costi della Tecnica.","aggiunta":true},{"type":"p","style":"Normal","text":"Esempio con 8 ST disponibili dopo l’attacco iniziale: puoi effettuare tre attacchi base extra pagando 1 + 2 + 3 = 6 ST. Il quarto costerebbe 4 ST e non può essere acquistato con le 2 ST rimaste. Se utilizzi invece una Tecnica da 2 ST per gli attacchi extra, il primo costa 3 ST complessivi e il secondo 4 ST, per un totale di 7 ST. Rimane 1 ST e non puoi pagare il terzo, che costerebbe 5 ST complessivi."},{"type":"p","style":"Normal","text":"Esempio con mobilità e precisione: il primo attacco extra con una Tecnica contenente Scatto costa almeno 2 ST, di cui 1 per Raffica e 1 per Scatto, e consuma soltanto i metri effettivamente percorsi dal budget di Tecnica. Il primo attacco extra con Punto di Rottura costa almeno 3 ST, di cui 1 per Raffica e 2 per l’effetto, e richiede Precisione Assoluta. Gli altri effetti si pagano normalmente."}],"frequency":"turn","costProgression":"extra-index"},{"id":"fendente-sovrano","name":"Fendente Sovrano","paths":["swordsman"],"requires":["Fendente d'Aria"],"replaces":["Fendente d'Aria"],"action":"modifier","costST":1,"saikyoST":1,"match":"blade","uses":null,"saikyoUses":null,"resource":null,"source":"combattenti","start":218,"end":225,"anchor":"combattenti-fendente-sovrano","blocks":[{"type":"p","style":"Normal","text":"Evoluzione di: Fendente d’Aria. Tipo: passivo. Costo aggiuntivo per utilizzo: 1 ST. Requisito di impiego: una Tecnica offensiva Swordsman da mischia compatibile, eseguita con una lama."},{"type":"p","style":"Normal","text":"Quando utilizzi la Tecnica, puoi scagliare un fendente che raggiunge il bersaglio entro la portata della scala. Il costo di 1 ST si aggiunge a quello della Tecnica. Non richiede un’Azione Bonus separata."},{"type":"p","style":"Normal","text":"Il danno finale rimane pieno: il dimezzamento di Fendente d’Aria viene eliminato. Il Talento sostituisce la sua versione ordinaria e non richiede di pagarla una seconda volta."},{"type":"p","style":"Normal","text":"Effettua il normale tiro per colpire della Tecnica. Il bersaglio utilizza le proprie difese e coperture secondo le regole generali. Il fendente percorre lo spazio fra te e il punto colpito; gli ostacoli possono intercettarlo e devono essere superati o danneggiati secondo le loro regole."},{"type":"p","style":"Normal","text":"La Tecnica conserva i propri effetti, slot e costi. Una Tecnica Singolo continua a colpire un solo bersaglio. Area Ravvicinata dello Swordsman conserva Grado minimo d8 e costo 2 ST: non può essere proiettata a distanza tramite Fendente Sovrano, rimane centrata sul personaggio e il raggio è pari alla Portata effettiva della lama. Fendenti ad Area a distanza richiedono una capacità che li conceda espressamente. Gli effetti che richiedono contatto fisico mantengono quella condizione."},{"type":"p","style":"Normal","text":"Esempio: utilizzi una Tecnica basata sull’Attributo Tecnica d20+d10. Puoi raggiungere un nemico fino a 100 m. La Tecnica costa 3 ST e il suo danno finale è 28: con Fendente Sovrano paghi 4 ST e, se colpisci, infliggi 28 danni prima delle riduzioni del bersaglio."}],"frequency":"combat"},{"id":"taglio-colossale","name":"Taglio Colossale","paths":["swordsman"],"requires":[],"replaces":[],"action":"bonus","costST":2,"saikyoST":2,"match":"blade","uses":null,"saikyoUses":null,"resource":null,"source":"combattenti","start":225,"end":236,"anchor":"combattenti-taglio-colossale","blocks":[{"type":"p","style":"Normal","text":"Tipo: attivo. Attivazione: 1 Azione Bonus prima del colpo. Costo aggiuntivo: 2 ST. Durata: il prossimo attacco con una lama nel tuo turno. Bersaglio del beneficio: un solo elemento dello scenario."},{"type":"p","style":"Normal","text":"Scegli cosa vuoi recidere: uno scafo, un pilastro, una parete, una massa di roccia o una sezione di una struttura più grande. La sezione scelta deve rientrare nella dimensione massima concessa dall’Attributo del colpo. Il GM definisce i PS e le eventuali resistenze dell’elemento prima del tiro."},{"type":"p","style":"Normal","text":"Devi poter colpire un punto utile di quell’elemento con la normale portata dell’attacco. Per un taglio a distanza puoi utilizzare una Tecnica con Fendente Sovrano, pagando anche il suo costo."},{"type":"p","style":"Normal","text":"Se il colpo riesce, il danno contro l’elemento scelto è:"},{"type":"p","style":"Normal","text":"Danno strutturale = danno normale dell’attacco + un tiro completo dell’Attributo utilizzato."},{"type":"p","style":"Normal","text":"Il tiro aggiuntivo è un tiro di danno distinto dal tiro per colpire. Tiralo una sola volta, compreso il dado di Prestigio, e somma i risultati. Con Forza d20+d8 aggiungi d20+d8; con Attributo Tecnica d20+d12 aggiungi d20+d12."},{"type":"p","style":"Normal","text":"Applica le resistenze pertinenti e sottrai il danno ricevuto dai PS dell’elemento. Se il danno azzera i suoi PS, lo recidi con quel singolo fendente. Se restano PS, l’elemento viene danneggiato. Per gli elementi privi di PS, il GM determina il risultato usando le normali regole degli oggetti e dei materiali."},{"type":"p","style":"Normal","text":"Ogni utilizzo riguarda un elemento e applica il danno una sola volta. La dimensione massima indica quanto può essere grande la recisione; non moltiplica il danno. Contro una creatura questo Talento non aggiunge il bonus strutturale. Le conseguenze del cedimento, come una parete che crolla o uno scafo che si apre, vengono risolte separatamente."},{"type":"p","style":"Normal","text":"L’Azione Bonus e i 2 ST vengono spesi prima dell’attacco e rimangono consumati se manchi. Il potenziamento termina dopo quel colpo o alla fine del tuo turno."},{"type":"p","style":"Normal","text":"Esempio: scegli un pilastro con 40 PS, con una sezione entro la tua scala. Il colpo infligge 25 danni e il tiro completo dell’Attributo aggiunge 18. Il danno strutturale è 43: se il pilastro non possiede riduzioni pertinenti, lo recidi. Un pilastro con 60 PS rimarrebbe invece a 17 PS."}],"frequency":"combat"},{"id":"guardia-invalicabile","name":"Guardia Invalicabile","paths":["swordsman"],"requires":["Parata Perfetta"],"replaces":["Parata Perfetta"],"action":"reaction","costST":2,"saikyoST":2,"match":"parry","uses":null,"saikyoUses":null,"resource":null,"source":"combattenti","start":236,"end":246,"anchor":"combattenti-guardia-invalicabile","blocks":[{"type":"p","style":"Normal","text":"Evoluzione di: Parata Perfetta. Tipo: reattivo. Costo aggiuntivo: 2 ST e la tua Reazione. Requisito di impiego: una Parata con una lama contro un attacco intercettabile."},{"type":"p","style":"Normal","text":"Quando tenti la Parata, puoi spendere 2 ST per aggiungere un tiro completo di Atletica al normale tiro difensivo. Con Atletica in Prestigio tiri entrambi i dadi e sommi i risultati."},{"type":"p","style":"Normal","text":"Tiro di Guardia Invalicabile = Attributo della Parata + Dado Arma + tiro completo di Atletica."},{"type":"p","style":"Normal","text":"Il tiro viene confrontato con il risultato dell’attacco secondo le regole generali della Parata. Puoi intercettare un singolo attacco fisicamente contrastabile con la lama, anche di grandi dimensioni o ad area. Compatibilità della difesa e condizioni richieste dai poteri coinvolti continuano ad applicarsi."},{"type":"p","style":"Normal","text":"Una Parata riuscita protegge te e gli alleati entro 5 m dietro la tua posizione rispetto alla provenienza del colpo, purché la tua intercettazione copra effettivamente la sua traiettoria verso di loro. Un unico tiro risolve la difesa contro quell’attacco."},{"type":"p","style":"Normal","text":"Puoi così intercettare una cannonata prima che raggiunga la ciurma o fermare il fronte di un grande fendente. Attacchi distinti richiedono difese distinte e Reazioni disponibili. Se la Parata fallisce, il colpo viene risolto normalmente contro i suoi bersagli."},{"type":"p","style":"Normal","text":"Mantieni il ritentativo di Parata Perfetta: una volta per scontro, dopo una Parata fallita puoi ripetere il tiro e devi accettare il secondo risultato. Il ritentativo ripete il tiro completo di Guardia Invalicabile, senza una seconda spesa dei suoi 2 ST o un’altra Reazione."},{"type":"p","style":"Normal","text":"I 2 ST si aggiungono agli eventuali costi della capacità difensiva impiegata. Guardia Invalicabile utilizza la Reazione ordinaria e non richiede l’Azione Bonus. Il Talento potenzia la Parata e non assegna un attacco in risposta."},{"type":"p","style":"Normal","text":"Esempio: una cannonata viene risolta con un risultato per colpire di 38. La tua normale Parata produce 24; il tiro completo di Atletica produce 19. Il totale è 43: la Parata riesce e protegge anche i compagni nella posizione coperta dietro di te."}],"frequency":"combat"},{"id":"maestria-assoluta-della-lama","name":"Maestria Assoluta della Lama","paths":["swordsman"],"requires":[],"replaces":[],"action":"passive","costST":0,"saikyoST":0,"match":"parry","uses":null,"saikyoUses":null,"resource":null,"source":"combattenti","start":246,"end":257,"anchor":"combattenti-maestria-assoluta-della-lama","blocks":[{"type":"p","style":"Normal","text":"Tipo: passivo. Costo aggiuntivo: 0 ST. Applicazione: qualsiasi lama compatibile che impugni."},{"type":"p","style":"Normal","text":"Qualsiasi lama che impugni utilizza d20 come Dado Arma, indipendentemente dal suo Grado originario."},{"type":"p","style":"List Bullet","text":"Attacco base: Attributo previsto dalla lama + d20."},{"type":"p","style":"List Bullet","text":"Danno dell’attacco base: 1d20, più i benefici compatibili."},{"type":"p","style":"List Bullet","text":"Parata: Attributo previsto dalla difesa + d20."},{"type":"p","style":"Normal","text":"Un coltello d4, una sciabola d8 e una katana d12 utilizzano quindi d20 per questi tiri nelle tue mani. Il Talento usa sempre d20: il Prestigio di Atletica ne sblocca l’acquisizione e non aggiunge un ulteriore dado al Dado Arma."},{"type":"p","style":"Normal","text":"La lama conserva portata, proprietà ed eventuali effetti speciali. I requisiti per impugnarla dipendono dal suo Grado originario. La maestria appartiene allo Swordsman: quando un altro personaggio impugna quell’arma, utilizza il suo normale Grado."},{"type":"p","style":"Normal","text":"Le Tecniche Swordsman continuano a utilizzare il proprio Dado Tecnica per colpire e il proprio Dado Danno. Una Tecnica d8 rimane d8 anche se viene eseguita con una lama che utilizzi come d20. La Firma Doppio fendente segue il Dado Danno del colpo: su un attacco base con Maestria aggiunge d20; su una Tecnica aggiunge il Dado Danno previsto da quella mossa."},{"type":"p","style":"Normal","text":"Maestria Assoluta della Lama può accompagnare Guardia Invalicabile: usa d20 come Dado Arma nella sua formula e aggiungi il tiro completo di Atletica una sola volta."},{"type":"p","style":"Normal","text":"Esempio: impugni un coltello d4 associato all’Attributo Tecnica. Con Attributo Tecnica d20+d8, l’attacco base utilizza d20+d8+d20. Se colpisci, il danno base è 1d20. Con un colpo pulito, la Firma aggiunge un altro d20, per un totale di 2d20 prima degli altri benefici applicabili."}],"frequency":"combat"},{"id":"maglio-inarrestabile","name":"Maglio Inarrestabile","paths":["crusher"],"requires":["Colpo Pesante — Maestria"],"replaces":["Colpo Pesante — Base","Colpo Pesante — Migliorato","Colpo Pesante — Maestria"],"action":"modifier","costST":3,"saikyoST":3,"match":"blunt","uses":1,"saikyoUses":1,"resource":null,"source":"combattenti","start":261,"end":271,"anchor":"combattenti-maglio-inarrestabile","blocks":[{"type":"p","style":"Normal","text":"Evoluzione di: Colpo Pesante Maestria. Prerequisito: possedere Colpo Pesante Maestria. Tipo: attivo, modificatore del colpo. Attivazione: dichiarazione prima dell’attacco, senza Azione Bonus aggiuntiva. Costo: 3 ST complessivi al posto delle 2 ST di Maestria. Limite: 1 volta nel tuo turno."},{"type":"p","style":"Normal","text":"Puoi accompagnare un attacco base o una Tecnica offensiva in mischia del Crusher eseguita con un’arma contundente compatibile. Paghi le 3 ST alla dichiarazione, oltre agli eventuali costi della Tecnica. Questa versione sostituisce Colpo Pesante Maestria e mantiene Vantaggio al tiro per colpire, +2 Dadi Danno e Sbilanciamento del bersaglio se il colpo va a segno."},{"type":"p","style":"Normal","text":"La tua DP diminuisce di 5 dalla dichiarazione fino all’inizio del tuo prossimo turno. La penalità e il costo restano anche se il colpo manca, viene schivato o viene parato. Le versioni Base, Migliorato, Maestria e Maglio Inarrestabile non si sommano per ripetere bonus o penalità."},{"type":"p","style":"Normal","text":"Inoltre, tira separatamente una volta Forza, compreso il suo eventuale dado di Prestigio, e aggiungi il risultato al danno del colpo. Il tiro aggiuntivo riguarda soltanto questo attacco e non modifica il tiro per colpire."},{"type":"p","style":"Normal","text":"Danno di Maglio Inarrestabile = danno di Colpo Pesante Maestria + un tiro completo di Forza."},{"type":"p","style":"Normal","text":"Se l’attacco supera la difesa necessaria per colpire ma il bersaglio lo ferma con una Parata riuscita, subisce comunque metà del danno complessivo, arrotondata per difetto, e poi applica le proprie riduzioni. La Parata trattiene l’arma ma trasmette parte dell’impatto."},{"type":"p","style":"Normal","text":"Il danno residuo di un colpo parato non applica Sbilanciamento, la Firma, Proiezione, Schianto o altri effetti del colpo. Non conta come colpo riuscito per attivare Onda Sismica, Guardia Frantumata o Rompiguardia. Le altre difese conservano le proprie regole: una Schivata riuscita evita l’attacco e un tiro che non supera la difesa necessaria per colpire non infligge neppure il danno dimezzato."},{"type":"p","style":"Normal","text":"Se invece il colpo va normalmente a segno, si applicano il danno intero e gli effetti compatibili. Per una successiva propagazione valida con Onda Sismica, D comprende anche questo tiro aggiuntivo di Forza. Un eventuale Schianto utilizza il proprio distinto tiro di Forza e non riceve nuovamente il bonus di Maglio Inarrestabile."},{"type":"p","style":"Normal","text":"Esempio: il danno di Maestria è 30 e il tiro aggiuntivo di Forza dà 18. Il danno diventa 48 prima delle riduzioni. Se il colpo va a segno, il bersaglio riceve 48 danni e viene Sbilanciato; se lo para con successo dopo che l’attacco ha superato la difesa necessaria, riceve 24 danni prima delle riduzioni e gli altri effetti vengono fermati. In entrambi i casi il Crusher ha speso 3 ST e mantiene DP −5 per la durata prevista."}],"frequency":"turn"},{"id":"onda-sismica","name":"Onda Sismica","paths":["crusher"],"requires":["Impatto a Catena"],"replaces":["Impatto a Catena","Onda d'Urto"],"action":"bonus","costST":3,"saikyoST":3,"match":"seismic","uses":1,"saikyoUses":1,"resource":null,"source":"combattenti","start":271,"end":285,"anchor":"combattenti-onda-sismica","blocks":[{"type":"p","style":"Normal","text":"Evoluzione di: Impatto a Catena. Prerequisito: possedere Impatto a Catena. Tipo: attivo. Attivazione: 1 Azione Bonus dopo un colpo riuscito nel tuo turno. Costo: 3 ST complessivi al posto delle 2 ST di Onda d’Urto. Limite: 1 volta nel tuo turno. Per questa onda: Forza almeno d20+d4 e un impatto valido su una superficie."},{"type":"p","style":"Normal","text":"Quando un tuo attacco contundente basato su Forza colpisce il terreno, un oggetto, una struttura o una creatura e l’impatto si trasmette a una superficie, puoi spendere l’Azione Bonus e 3 ST per attaccare anche le creature appoggiate a quella superficie. Può essere un attacco base oppure una Tecnica offensiva compatibile. Un colpo mancato, schivato o parato non consente l’attivazione."},{"type":"p","style":"Normal","text":"La sola scala di distruzione ti permette già di danneggiare lo scenario senza questi costi. Onda Sismica aggiunge danni diretti, spinta e Sbilanciamento contro le creature: usa il raggio esistente di Forza e non crea una seconda scala di distruzione."},{"type":"p","style":"Normal","text":"L’onda parte dal punto d’impatto e percorre un cono di 90°. Quando la attivi, dichiara la direzione e la lunghezza scelta, fino al raggio massimo della tua Forza. Per esempio, con Forza d20+d10 il cono può estendersi fino a 100 m; a Saikyō fino a 1.000 m. Le fasce di danno restano calcolate sul raggio massimo di Forza, anche se scegli un cono più corto."},{"type":"p","style":"Normal","text":"Onda Sismica nasce sempre da un singolo impatto valido e segue la propria sagoma di Prestigio. Area Ravvicinata del Crusher, se presente nella Tecnica, conserva Grado minimo d8 e costo 2 ST, rimane centrata sul personaggio e ha raggio pari alla Portata effettiva dell’arma: non genera più coni, non crea nuovi centri di Onda Sismica e non ne aumenta il raggio.","aggiunta":true},{"type":"p","style":"Normal","text":"Deve essere identificabile il singolo punto in cui l’impatto contundente si scarica sulla superficie: da quel punto si risolve l’intera onda. Un’Area più ampia concessa da una Fonte speciale resta separata; Area e cono di Prestigio non aumentano reciprocamente le proprie dimensioni.","aggiunta":true},{"type":"p","style":"Normal","text":"Sono coinvolte soltanto le creature appoggiate al terreno o alla superficie materialmente collegata che l’onda raggiunge. Non basta trovarsi sopra il cono mentre si vola o si è sospesi senza contatto. Un ostacolo che resiste può fermare la propagazione e una superficie separata non viene raggiunta automaticamente. Il Crusher che genera l’onda è escluso; gli alleati nella zona possono essere colpiti e non possono essere esclusi liberamente."},{"type":"p","style":"Normal","text":"Usa il risultato del tiro per colpire originario contro ciascuna creatura aggiuntiva, risolvendo DP, Difese Attive, Reazioni e coperture secondo le regole normali. Se il colpo contro una superficie non richiedeva un tiro, effettua un unico normale tiro per colpire valido per l’onda. Ogni creatura può subire un esito diverso."},{"type":"p","style":"Normal","text":"Tira il danno iniziale una sola volta e usalo come D, includendo Maglio Inarrestabile e gli altri bonus applicabili al colpo, ma escludendo un eventuale Schianto successivo. Ciascuna creatura aggiuntiva colpita riceve la frazione prevista dalla distanza, poi applica le proprie riduzioni; viene inoltre spinta di 3 m in direzione di allontanamento dall’impatto e Sbilanciata, salvo protezioni pertinenti. Uno stato già presente non si somma a una seconda copia dello stesso stato."},{"type":"p","style":"Normal","text":"Il bersaglio iniziale ha già ricevuto il colpo e non riceve una seconda copia del danno, della spinta o dello Sbilanciamento da questa onda. Gli altri effetti della Tecnica e la Firma non si estendono ai bersagli aggiuntivi. Le strutture raggiunte ricevono una sola applicazione del danno della propria fascia: la scala passiva e il Talento descrivono lo stesso impatto."},{"type":"p","style":"Normal","text":"Il cono sostituisce il limite di tre nemici aggiuntivi entro 3 m di Impatto a Catena. Non paghi anche le 2 ST della versione precedente e non aggiungi una seconda onda attraverso Onda d’Urto. Onda Sismica rende indisponibile Impatto a Catena come scelta separata; i suoi benefici vengono incorporati nell’evoluzione."},{"type":"p","style":"Normal","text":"La spinta dell’onda resta di 3 m: non diventa un lancio da 100 m e non genera automaticamente Schianto. Proiezione Colossale e il relativo danno da urto riguardano il bersaglio della Tecnica che contiene effettivamente Proiezione e, per il danno, Schianto."},{"type":"p","style":"Normal","text":"Esempio: con Forza d20+d10 colpisci il suolo e il danno iniziale è 40. Senza il Talento puoi danneggiare lo scenario entro il raggio scelto, fino a 100 m. Se attivi Onda Sismica pagando l’Azione Bonus e 3 ST, una creatura colpita a 20 m nel cono riceve 40 danni, a 40 m ne riceve 20, a 60 m ne riceve 10 e a 90 m ne riceve 5, prima delle riduzioni. Le creature colpite vengono anche spinte di 3 m e Sbilanciate, se prive di protezioni pertinenti."}],"frequency":"turn"},{"id":"guardia-frantumata","name":"Guardia Frantumata","paths":["crusher"],"requires":["Rompiguardia"],"replaces":["Rompiguardia"],"action":"passive","costST":0,"saikyoST":0,"match":"blunt","uses":1,"saikyoUses":1,"resource":null,"source":"combattenti","start":285,"end":293,"anchor":"combattenti-guardia-frantumata","blocks":[{"type":"p","style":"Normal","text":"Evoluzione di: Rompiguardia. Prerequisito: possedere Rompiguardia. Tipo: passivo. Costo aggiuntivo: 0 ST. Azione aggiuntiva: nessuna. Limite: 1 applicazione nel tuo turno."},{"type":"p","style":"Normal","text":"Quando un tuo attacco diretto con un’arma contundente compatibile ottiene un colpo pulito contro una creatura, con il normale margine almeno +4, puoi aprire completamente la sua guardia. Il bersaglio subisce il normale danno del colpo."},{"type":"p","style":"Normal","text":"Fino alla fine del suo prossimo turno non può effettuare Parate né utilizzare Difese Attive fondate sul blocco fisico del colpo. Può ancora schivare, allontanarsi e utilizzare difese che evitano l’attacco; conserva la propria DP e le riduzioni del danno. Una Tecnica difensiva può essere usata soltanto se il modo in cui evita l’attacco è compatibile con questa limitazione."},{"type":"p","style":"Normal","text":"L’effetto rappresenta l’arma scostata e la postura difensiva compromessa. Non distrugge automaticamente l’arma o lo scudo e non disattiva l’Haki, un Frutto o le riduzioni del bersaglio. Eventuali danni a un oggetto devono essere prodotti e risolti con le regole appropriate."},{"type":"p","style":"Normal","text":"Se il colpo scelto va a segno senza essere pulito, applica invece il normale Rompiguardia: la prossima Parata o Difesa Attiva del bersaglio, prima della fine del suo prossimo turno, avviene in Svantaggio. Le due versioni condividono questo impiego e non producono due penalità attraverso lo stesso colpo. Una nuova applicazione non somma ulteriori divieti o durate contemporanee."},{"type":"p","style":"Normal","text":"Un attacco mancato, evitato o parato non attiva il Talento. Il danno residuo di Maglio Inarrestabile dopo una Parata riuscita non apre la guardia. Onda Sismica non distribuisce Guardia Frantumata a tutte le creature raggiunte: l’effetto riguarda il bersaglio diretto del colpo scelto."},{"type":"p","style":"Normal","text":"Esempio: nel tuo turno colpisci con un margine pulito un nemico che combatte con uno scudo. Fino alla fine del suo prossimo turno non può fermare i colpi con lo scudo o una Parata, ma può schivare e conserva le proprie altre difese compatibili. Lo scudo rimane integro finché non subisce danni strutturali sufficienti a romperlo."}],"frequency":"turn"},{"id":"arresto-del-colosso","name":"Arresto del Colosso","paths":["crusher"],"requires":["Colpo di Intercettazione","Baricentro Assoluto"],"replaces":["Colpo di Intercettazione"],"action":"reaction","costST":3,"saikyoST":3,"match":"baseOnly","uses":null,"saikyoUses":null,"resource":null,"source":"combattenti","start":293,"end":304,"anchor":"combattenti-arresto-del-colosso","blocks":[{"type":"p","style":"Normal","text":"Evoluzione di: Colpo di Intercettazione. Prerequisiti: possedere Colpo di Intercettazione e Baricentro Assoluto. Tipo: reattivo. Attivazione: 1 Reazione quando un nemico entra nella portata della tua arma durante un movimento. Costo: 3 ST. Limite: 1 volta per turno, usando la Reazione disponibile."},{"type":"p","style":"Normal","text":"Puoi utilizzare il Talento soltanto mentre soddisfi tutte le condizioni di Baricentro Assoluto: sei cosciente, sei a contatto con il terreno e non ti muovi volontariamente. Devi impugnare un’arma contundente compatibile e poter raggiungere il nemico nel momento in cui entra nella sua normale portata. La scala di distruzione non allunga la portata dell’intercettazione."},{"type":"p","style":"Normal","text":"Prima che il nemico prosegua il movimento oltre quel punto, spendi la Reazione e 3 ST ed esegui un attacco base contundente. Al normale tiro per colpire aggiungi un tiro completo di Atletica, incluso l’eventuale dado di Prestigio. Atletica si aggiunge al tiro per colpire e non al danno."},{"type":"p","style":"Normal","text":"Tiro di Arresto del Colosso = normale tiro per colpire dell’attacco base + un tiro completo di Atletica."},{"type":"p","style":"Normal","text":"Il nemico dispone delle proprie normali difese. Se il colpo va a segno e infligge danno effettivo, il suo movimento termina immediatamente e non può riprendere per il resto di quel turno. Una taglia superiore non annulla questa conseguenza: anche una creatura enorme può essere arrestata se l’attacco la colpisce e la danneggia."},{"type":"p","style":"Normal","text":"Puoi interrompere in questo modo una carica, uno scatto o un balzo quando il nemico attraversa effettivamente la portata dell’arma. Se interrompi un balzo, le cadute e la necessità di un appoggio si risolvono normalmente. Un movimento che non attraversa una posizione raggiungibile dall’arma non attiva l’intercettazione."},{"type":"p","style":"Normal","text":"Il bersaglio conserva le azioni ancora disponibili e può usarle dalla posizione in cui è stato fermato. L’effetto arresta il movimento e non assegna automaticamente uno Stordimento o l’annullamento di ogni sua azione. Una spinta subita successivamente o un altro spostamento forzato segue le proprie regole."},{"type":"p","style":"Normal","text":"Se manchi, il nemico evita il colpo oppure le sue riduzioni portano il danno effettivo a zero, il movimento non viene arrestato. Le 3 ST e la Reazione restano spese. Il Talento utilizza la stessa intercettazione della versione precedente, senza aggiungere un secondo attacco o una seconda Reazione. Arresto del Colosso rende indisponibile Colpo di Intercettazione come scelta separata."},{"type":"p","style":"Normal","text":"L’attacco conserva il normale danno base e gli effetti compatibili con un attacco base del Ruolo. Non diventa una Tecnica e non acquisisce Proiezione o Schianto gratuitamente. Maglio Inarrestabile richiede un utilizzo nel tuo turno; Onda Sismica richiede inoltre la tua Azione Bonus e le proprie condizioni. Questi Talenti non si aggiungono automaticamente a un’intercettazione nei turni altrui."},{"type":"p","style":"Normal","text":"Esempio: rimani piantato sul terreno e un gigante entra nella portata della tua mazza durante una carica. Spendi 3 ST e la Reazione, sommi Atletica al normale attacco base e colpisci. Se il gigante subisce danno dopo le riduzioni, si arresta in quel punto e non può continuare a muoversi nel turno, ma può ancora compiere le azioni possibili da quella posizione."}],"frequency":"combat"},{"id":"tiro-risolutivo","name":"Tiro Risolutivo","paths":["sniper"],"requires":["Respiro Trattenuto"],"replaces":["Respiro Trattenuto"],"action":"bonus","costST":2,"saikyoST":2,"match":"singleRanged","uses":null,"saikyoUses":null,"resource":null,"source":"combattenti","start":307,"end":315,"anchor":"combattenti-tiro-risolutivo","blocks":[{"type":"p","style":"Normal","text":"Evoluzione di: Respiro Trattenuto. Prerequisito: possedere Respiro Trattenuto. Tipo: attivo. Attivazione: 1 Azione Bonus prima del tiro. Costo aggiuntivo: 2 ST. Limite: 1 volta nel tuo turno."},{"type":"p","style":"Normal","text":"Prepari il prossimo attacco a distanza contro un singolo bersaglio, da effettuare entro la fine del tuo turno. Può essere un attacco base o una Tecnica offensiva compatibile. Se il colpo va a segno, aggiungi al danno un tiro completo di Astuzia, compreso il dado di Prestigio, e il colpo viene considerato pulito ai fini della Firma e degli altri effetti compatibili che richiedono quel risultato."},{"type":"p","style":"Normal","text":"Danno di Tiro Risolutivo = danno ordinario del colpo + un tiro completo di Astuzia."},{"type":"p","style":"Normal","text":"Il bersaglio mantiene le proprie difese. La qualifica di colpo pulito si applica soltanto dopo un attacco riuscito: non cambia il tiro per colpire e non trasforma un attacco mancato in un successo. Il danno complessivo subisce le normali riduzioni del bersaglio."},{"type":"p","style":"Normal","text":"Il beneficio si consuma con il prossimo attacco valido, anche se manca; se non lo esegui entro la fine del turno, termina. Le 2 ST vengono spese all'attivazione e si aggiungono agli eventuali costi della Tecnica. Il Talento riguarda un solo colpo contro un singolo bersaglio e non si distribuisce attraverso attacchi ad area, Rimbalzo o Catena."},{"type":"p","style":"Normal","text":"L'evoluzione usa questa attivazione e sostituisce il limite di Respiro Trattenuto con un utilizzo nel tuo turno. Le due versioni non si sommano per moltiplicare il beneficio. Il tiro aggiuntivo di Astuzia si applica una sola volta."},{"type":"p","style":"Normal","text":"Esempio: con Astuzia d20+d8, un colpo infligge normalmente 12 danni. Tiri separatamente Astuzia e ottieni 19: il danno diventa 31 prima delle riduzioni. Poiché il colpo è riuscito, viene anche considerato pulito e può attivare Il punto scoperto oppure Occhio del Falco, se posseduto."}],"frequency":"combat"},{"id":"precisione-chirurgica","name":"Precisione Chirurgica","paths":["sniper"],"requires":["Colpo Mirato"],"replaces":["Colpo Mirato"],"action":"modifier","costST":2,"saikyoST":2,"match":"singleRanged","uses":null,"saikyoUses":null,"resource":null,"source":"combattenti","start":315,"end":325,"anchor":"combattenti-precisione-chirurgica","blocks":[{"type":"p","style":"Normal","text":"Evoluzione di: Colpo Mirato. Prerequisito: possedere Colpo Mirato. Tipo: modificatore a un attacco a distanza contro un singolo bersaglio. Attivazione: dichiarazione prima del tiro, senza Azione Bonus. Costo aggiuntivo: 2 ST."},{"type":"p","style":"Normal","text":"Scegli un punto preciso e dichiari la conseguenza che vuoi produrre. Effettui il normale attacco contro le difese del bersaglio. Se ottieni un colpo pulito, infliggi il danno ordinario e applichi anche la conseguenza mirata, invece di rinunciare al danno come con Colpo Mirato."},{"type":"p","style":"List Bullet","text":"Mano: il bersaglio non può utilizzare quella mano fino alla fine del suo prossimo turno."},{"type":"p","style":"List Bullet","text":"Gamba: il bersaglio non può effettuare Movimento volontario fino alla fine del suo prossimo turno."},{"type":"p","style":"List Bullet","text":"Oggetto o componente: concentri il danno sull'elemento scelto; se raggiunge 0 PS, lo rompi oppure ne interrompi il funzionamento."},{"type":"p","style":"Normal","text":"Il punto scelto deve essere raggiungibile dalla traiettoria. Una mano o una gamba viene neutralizzata temporaneamente: questo effetto non produce automaticamente una mutilazione. Sullo stesso bersaglio può essere attiva una sola neutralizzazione di un arto; una nuova applicazione sostituisce quella precedente."},{"type":"p","style":"Normal","text":"Se colpisci senza ottenere un colpo pulito, infliggi soltanto il danno ordinario. Se manchi, non infliggi danno e non applichi la conseguenza. Le 2 ST si pagano anche se il tiro manca o non soddisfa il requisito. Restano i costi dell'attacco o della Tecnica utilizzata."},{"type":"p","style":"Normal","text":"Quando colpisci un oggetto, il danno si applica al componente effettivamente scelto, con i suoi PS e la sua resistenza. Non infliggi lo stesso danno anche alla creatura che lo impugna o all'intera struttura. L'effetto dell'evoluzione non si somma a una seconda conseguenza gratuita di Colpo Mirato sullo stesso tiro."},{"type":"p","style":"Normal","text":"Esempio: un ufficiale sta per utilizzare un cannone. Colpisci la sua mano con un colpo pulito: infliggi il normale danno all'ufficiale e gli impedisci di usare quella mano fino alla fine del suo prossimo turno. Se invece scegli il meccanismo del cannone, il danno si applica a quel componente e lo interrompe soltanto se lo porta a 0 PS."}],"frequency":"combat"},{"id":"interdizione-sovrana","name":"Interdizione Sovrana","paths":["sniper"],"requires":["Colpo Anticipato"],"replaces":["Colpo Anticipato"],"action":"reaction","costST":2,"saikyoST":2,"match":"ranged","uses":null,"saikyoUses":null,"resource":null,"source":"combattenti","start":325,"end":333,"anchor":"combattenti-interdizione-sovrana","blocks":[{"type":"p","style":"Normal","text":"Evoluzione di: Colpo Anticipato. Prerequisito: possedere Colpo Anticipato. Tipo: reattivo. Attivazione: 1 Reazione quando un nemico osservato dichiara un'Azione, prima che la completi. Costo aggiuntivo: 2 ST."},{"type":"p","style":"Normal","text":"Attacchi il nemico prima che completi l'Azione dichiarata, con un attacco a distanza valido e rispettando gittata, percorso e disponibilità dell'arma. Se il tiro va a segno, infliggi il danno normale e l'Azione avversaria avviene in Svantaggio, come con Colpo Anticipato."},{"type":"p","style":"Normal","text":"Se ottieni un colpo pulito, puoi invece impedire quell'Azione, purché il tiro interrompa concretamente ciò che serve a eseguirla. Puoi colpire la mano prima dello sparo, rompere il comando prima dell'attivazione oppure interrompere il gesto necessario a una Tecnica. Il punto e il modo in cui il colpo ostacola la manovra devono essere dichiarati prima del tiro. Se l'interruzione richiede di rompere un componente, valgono i suoi PS e la sua resistenza."},{"type":"p","style":"Normal","text":"L'avversario consuma l'Azione dichiarata e conserva le altre risorse e possibilità del turno. Le risorse già spese per quell'Azione restano spese. Un colpo pulito che non può interrompere materialmente la manovra applica il normale Svantaggio, senza annullarla."},{"type":"p","style":"Normal","text":"Il Talento riguarda una manovra ancora da completare: un proiettile già partito segue normalmente la propria risoluzione. Un attacco mancato non penalizza né interrompe l'Azione nemica. La Reazione e le 2 ST vengono comunque spese; un'eventuale Tecnica paga anche i propri costi."},{"type":"p","style":"Normal","text":"L'evoluzione usa la stessa Reazione del tiro anticipato e non concede una seconda Reazione o un altro attacco attraverso Colpo Anticipato. Puoi applicarla soltanto se disponi della Reazione richiesta."},{"type":"p","style":"Normal","text":"Esempio: osservi un tiratore nemico che dichiara di sparare contro un alleato. Spendi la Reazione e 2 ST e attacchi la mano che tiene l'arma. Se colpisci senza un colpo pulito, il suo tiro avviene in Svantaggio; se ottieni un colpo pulito e la manovra può essere interrotta in questo modo, il nemico consuma l'Azione senza completare lo sparo."}],"frequency":"combat"},{"id":"danza-dei-proiettili","name":"Danza dei Proiettili","paths":["sniper"],"requires":[],"replaces":[],"action":"modifier","costST":1,"saikyoST":1,"match":"ricochet","uses":null,"saikyoUses":null,"resource":null,"source":"combattenti","start":333,"end":342,"anchor":"combattenti-danza-dei-proiettili","blocks":[{"type":"p","style":"Normal","text":"Tipo: modificatore passivo delle Tecniche Sniper con Rimbalzo oppure Catena. Costo aggiuntivo: 1 ST per utilizzo, oltre ai costi della Tecnica. Attivazione: nessuna Azione Bonus aggiuntiva. Requisito di impiego: una Tecnica compatibile che contenga uno dei due effetti, con il relativo slot."},{"type":"p","style":"Normal","text":"Quando utilizzi una Tecnica Sniper con Rimbalzo o Catena, ogni bersaglio raggiunto riceve il danno pieno della mossa, sostituendo la riduzione progressiva prevista dall'effetto."},{"type":"p","style":"List Bullet","text":"Rimbalzo: fino a due bersagli, rispettando il limite ordinario di 5 m fra il primo e il secondo."},{"type":"p","style":"List Bullet","text":"Catena: fino a tre bersagli disposti in fila, rispettando gli altri requisiti dell'effetto."},{"type":"p","style":"Normal","text":"Effettui un tiro per colpire separato contro ciascun bersaglio e tiri il danno una sola volta. Ogni bersaglio applica normalmente difese e riduzioni. Un bersaglio mancato non riceve danno e nessun bersaglio può essere colpito due volte dalla stessa sequenza."},{"type":"p","style":"Normal","text":"Il Talento modifica il danno degli effetti già presenti nella Tecnica; non concede nuovi slot o un numero maggiore di bersagli. Rimbalzo e Catena restano alternative della stessa famiglia e non vengono sommati per aumentare il numero di colpi."},{"type":"p","style":"Normal","text":"Se il percorso richiede traiettorie anomale, utilizzi anche Colpo Impossibile, pagando i suoi 2 ST e rispettando il numero di deviazioni consentito da Astuzia. Geometria del Tiro può modificare il percorso, ma non elimina le distanze e la disposizione richieste da Rimbalzo o Catena."},{"type":"p","style":"Normal","text":"Esempio: una Tecnica con Catena colpisce tre nemici in fila e il danno tirato è 18. Con Danza dei Proiettili ogni nemico colpito riceve 18 danni prima delle proprie riduzioni, invece di 18, 9 e 4. Se l'unico costo ordinario della Tecnica è Catena da 2 ST, l'utilizzo costa 3 ST complessivi: 2 per Catena e 1 per il Talento."}],"frequency":"combat"},{"id":"ordine-sovrano","name":"Ordine Sovrano","paths":["capitano"],"requires":["Ordine del Capitano — Maestria"],"replaces":["Ordine del Capitano — Base","Ordine del Capitano — Migliorato","Ordine del Capitano — Maestria"],"action":"bonus","costST":3,"saikyoST":4,"match":"support","uses":3,"saikyoUses":3,"resource":null,"source":"ruoli","start":29,"end":34,"anchor":"ruoli-ordine-sovrano","blocks":[{"type":"p","style":"Normal","text":"Evolve: Ordine del Capitano — Maestria. Attivazione: Azione Bonus. Costo: 3 ST. Limite: 3 ordini per combattimento."},{"type":"p","style":"Normal","text":"Scegli un alleato che possa vederti o sentirti. Il compagno esegue immediatamente un Movimento e un’Azione fuori dal proprio turno, conservando il Vantaggio previsto dalla Maestria. L’intervento non consuma il suo normale turno."},{"type":"p","style":"Normal","text":"L’alleato paga i costi delle Tecniche e delle altre capacità che utilizza. Il Talento non concede un’Azione Bonus aggiuntiva. Il limite di tre ordini sostituisce quello di due della Maestria ed è condiviso con gli ordini ordinari."},{"type":"p","style":"Normal","text":"Saikyō: spendendo 4 ST, impartisci lo stesso ordine a due alleati. Ciascuno ottiene il proprio Movimento e la propria Azione con i benefici della Maestria. L’ordine conta come un solo utilizzo dei tre disponibili."}],"frequency":"combat"},{"id":"grido-leggendario","name":"Grido Leggendario","paths":["capitano"],"requires":["Grido di Guerra"],"replaces":["Grido di Guerra"],"action":"bonus","costST":3,"saikyoST":5,"match":"support","uses":1,"saikyoUses":1,"resource":null,"source":"ruoli","start":34,"end":39,"anchor":"ruoli-grido-leggendario","blocks":[{"type":"p","style":"Normal","text":"Evolve: Grido di Guerra. Attivazione: Azione Bonus. Costo: 3 ST. Limite: una volta per combattimento, condiviso con Grido di Guerra."},{"type":"p","style":"Normal","text":"Gli alleati che ti sentono rimuovono uno Stato negativo rimovibile, come nella capacità ordinaria. Al loro prossimo tiro aggiungono il risultato di un tuo tiro completo di Comunicazione, sostituendo il normale dado bonus di Grido di Guerra."},{"type":"p","style":"Normal","text":"Tiri Comunicazione una sola volta, senza aggiungere Spirito. Tutti i compagni interessati ricevono lo stesso risultato. Il bonus si applica al tiro della prova, compreso un tiro per colpire pertinente, e non si aggiunge direttamente ai danni."},{"type":"p","style":"Normal","text":"Saikyō: spendendo 5 ST, lo stesso risultato si applica ai prossimi due tiri di ciascun alleato, anziché a uno. Il limite resta una volta per combattimento."}],"frequency":"combat"},{"id":"il-piano-perfetto","name":"Il Piano Perfetto","paths":["capitano"],"requires":["Il Piano"],"replaces":["Il Piano"],"action":"preparation","costST":0,"saikyoST":0,"match":"outside","uses":6,"saikyoUses":8,"resource":null,"source":"ruoli","start":39,"end":45,"anchor":"ruoli-il-piano-perfetto","blocks":[{"type":"p","style":"Normal","text":"Evolve: Il Piano. Attivazione: preparazione dello scontro. Riserva: 6 ridadi condivisi."},{"type":"p","style":"Normal","text":"Quando prepari uno scontro secondo le condizioni di Il Piano, la ciurma dispone di sei ridadi condivisi, anziché quattro. Ogni punto conserva il normale uso previsto per un ridadi."},{"type":"p","style":"Normal","text":"Puoi impiegare la stessa riserva per una Contromossa. Quando percepisci la dichiarazione di un attacco nemico, prima del tiro per colpire, spendi la tua Reazione e due ridadi. Scegli due alleati raggiunti dai tuoi comandi, includendo eventualmente te stesso: ciascuno si muove immediatamente fino alla propria Velocità senza provocare attacchi di Reazione dovuti al disimpegno."},{"type":"p","style":"Normal","text":"Chi esce effettivamente dalla portata o dall’area dell’attacco evita di esserne coinvolto. Chi resta nel suo raggio d’azione risolve normalmente le difese. La Contromossa usa la riserva condivisa e non crea punti aggiuntivi."},{"type":"p","style":"Normal","text":"Saikyō: la riserva diventa otto ridadi e una Contromossa può spostare tre personaggi. Il costo resta una Reazione e due punti della stessa riserva."}],"frequency":"plan"},{"id":"orchestra-vivente","name":"Orchestra Vivente","paths":["musicista"],"requires":["Contrappunto — Maestria"],"replaces":["Contrappunto — Base","Contrappunto — Migliorato","Contrappunto — Maestria"],"action":"passive","costST":0,"saikyoST":0,"match":"song","uses":null,"saikyoUses":null,"resource":null,"source":"ruoli","start":47,"end":54,"anchor":"ruoli-orchestra-vivente","blocks":[{"type":"p","style":"Normal","text":"Evolve: Contrappunto — Maestria. Tipo: passivo. Costo aggiuntivo: nessuno."},{"type":"p","style":"Normal","text":"Puoi mantenere tre Canzoni attive contemporaneamente, conservando il mantenimento gratuito in ST della Maestria."},{"type":"p","style":"Normal","text":"Con una sola Azione puoi intonare due Canzoni distinte. Paghi il costo di attivazione di entrambe; Fiato Lungo si applica separatamente a ciascuna. Le Canzoni conservano bersagli, portate, durate ed effetti propri."},{"type":"p","style":"Normal","text":"Copie della stessa Melodia non sommano lo stesso beneficio sul medesimo bersaglio. Possono essere dedicate a bersagli differenti. Orchestra Vivente non unisce due Melodie in una sola Tecnica."},{"type":"p","style":"Normal","text":"Le Canzoni Sostenute continuano a richiedere che il Musicista sia materialmente in grado di suonare e che i bersagli possano sentirlo. Orchestra Vivente modifica il numero di Canzoni e la loro attivazione, ma non permette di mantenerle durante Incoscienza, perdita dello strumento o altre condizioni che rendano materialmente impossibile l’esecuzione.","aggiunta":true},{"type":"p","style":"Normal","text":"Saikyō: puoi mantenere quattro Canzoni attive contemporaneamente. L’attivazione di due Canzoni con una sola Azione conserva il funzionamento descritto."}],"frequency":"combat"},{"id":"risonanza-leggendaria","name":"Risonanza Leggendaria","paths":["musicista"],"requires":[],"replaces":[],"action":"passive","costST":0,"saikyoST":0,"match":"song","uses":null,"saikyoUses":null,"resource":null,"source":"ruoli","start":54,"end":61,"anchor":"ruoli-risonanza-leggendaria","blocks":[{"type":"p","style":"Normal","text":"Tipo: passivo sulle Canzoni ordinarie. Costo aggiuntivo: nessuno."},{"type":"p","style":"Normal","text":"Le tue Canzoni raddoppiano il numero dei dadi di recupero della ST e dei dadi bonus alle prove degli alleati. Raddoppiano inoltre l’importo degli sconti in ST sulle Tecniche, rispettando il minimo di 1 ST quando previsto."},{"type":"p","style":"Normal","text":"Saikyō: questi valori diventano tripli rispetto alla Melodia ordinaria, sostituendo il raddoppio."},{"type":"table","rows":[["Melodia","Con Risonanza Leggendaria","A Saikyō"],["Motivetto del Vigore","Recupero di 2d6 ST","Recupero di 3d6 ST"],["Marcia di Guerra","+2d4 al tiro per colpire previsto","+3d4 al tiro per colpire previsto"],["Crescendo","Sconto di 4 ST sulla Tecnica prevista","Sconto di 6 ST sulla Tecnica prevista"]]},{"type":"p","style":"Normal","text":"Vantaggio, ridadi, portata, numero di bersagli, costi di attivazione e sconti in PIP mantengono il loro valore ordinario. Il Talento modifica soltanto i benefici numerici descritti; non modifica l’effetto dell’Ultimate Canzone dell’Anima."},{"type":"p","style":"Normal","text":"Risonanza Leggendaria aumenta il recupero di Motivetto del Vigore a 2d6, oppure 3d6 a Saikyō, ma non modifica il limite di una volta per scena per ciascun beneficiario.","aggiunta":true}],"frequency":"combat"},{"id":"requiem-sovrano","name":"Requiem Sovrano","paths":["musicista"],"requires":["Requiem"],"replaces":["Requiem"],"action":"action","costST":4,"saikyoST":5,"match":"outside","uses":null,"saikyoUses":null,"resource":null,"source":"ruoli","start":61,"end":67,"anchor":"ruoli-requiem-sovrano","blocks":[{"type":"p","style":"Normal","text":"Evolve: Requiem. Attivazione: Azione. Costo: 4 ST. Portata: raggio di 50 m."},{"type":"p","style":"Normal","text":"Intoni una versione superiore di Requiem. Tutti i nemici entro il raggio che possono sentirti effettuano una Salvezza di Spirito. La Soglia è determinata dal Grado di Prestigio attuale di Arte secondo la tabella universale delle Salvezze e Prestigio (§1.1). La Soglia dello strumento non viene sommata al valore di Prestigio."},{"type":"p","style":"Normal","text":"Chi fallisce subisce Svantaggio a tutti i tiri fino all’inizio del tuo turno successivo. Requiem Sovrano non infligge danni diretti e non richiede un tiro per colpire. Non utilizza separatamente Requiem Beffardo: questa forma ne sostituisce l’esecuzione quando viene utilizzata."},{"type":"p","style":"Normal","text":"Saikyō: costo 5 ST e raggio 500 metri. Se possiedi Coro della Ciurma e almeno due compagni partecipano realmente al canto, la portata raddoppia normalmente fino a 1.000 metri."},{"type":"p","style":"Normal","text":"Anche a queste distanze i bersagli devono essere realmente in grado di sentire la musica: il raggio non permette alla Canzone di attraversare automaticamente ostacoli che bloccano completamente il suono.","aggiunta":true}],"frequency":"combat"},{"id":"tossine-sovrane","name":"Tossine Sovrane","paths":["tossicologo"],"requires":["Tossine Raffinate — Maestria"],"replaces":["Tossine Raffinate — Base","Tossine Raffinate — Migliorato","Tossine Raffinate — Maestria"],"action":"passive","costST":0,"saikyoST":0,"match":"poison","uses":null,"saikyoUses":null,"resource":null,"source":"ruoli","start":69,"end":76,"anchor":"ruoli-tossine-sovrane","blocks":[{"type":"p","style":"Normal","text":"Evolve: Tossine Raffinate — Maestria. Tipo: passivo sui tuoi veleni."},{"type":"p","style":"Normal","text":"Quando una tua dose classificata come Veleno richiede una Salvezza, confronta la Soglia registrata nella scheda del veleno con la Soglia di Prestigio corrispondente al tuo Grado attuale di Medicina. Usa la più alta delle due. Questo beneficio sostituisce il normale +2 di Tossine Raffinate — Base e non si somma a esso."},{"type":"table","rows":[["Medicina","Soglia minima con Tossine Sovrane"],["d20+d4 · Prestigio I","13"],["d20+d6 · Prestigio II","14"],["d20+d8 · Prestigio III","15"],["d20+d10 · Prestigio IV","16"],["d20+d12 · Prestigio V","17"],["d20+d20 · Saikyō","21"]],"aggiunta":true},{"type":"p","style":"Normal","text":"Quando un bersaglio fallisce la Salvezza, riduci un Attributo a tua scelta di due gradini fino alla somministrazione di un antidoto efficace. La riduzione segue la progressione dei dadi, compresi i gradini di Prestigio, e non può portare l’Attributo sotto d4."},{"type":"p","style":"Normal","text":"Applicazioni ripetute sullo stesso Attributo non sommano le riduzioni."},{"type":"p","style":"Normal","text":"Saikyō: la riduzione diventa di tre gradini. Per la Salvezza confronta la Soglia propria del veleno con la Soglia minima 21 di Medicina a Saikyō e usa la più alta."}],"frequency":"combat"},{"id":"nebbia-pestilenziale","name":"Nebbia Pestilenziale","paths":["tossicologo"],"requires":["Nube Tossica"],"replaces":["Nube Tossica"],"action":"action","costST":4,"saikyoST":5,"match":"outside","uses":null,"saikyoUses":null,"resource":null,"source":"ruoli","start":76,"end":86,"anchor":"ruoli-nebbia-pestilenziale","blocks":[{"type":"p","style":"Normal","text":"Evolve: Nube Tossica. Attivazione: Azione. Costo: 4 ST. Durata: 3 turni. Posizionamento del centro: entro 20 m."},{"type":"p","style":"Normal","text":"Nebbia Pestilenziale utilizza e consuma una dose preparata di Veleno compatibile con Inalazione, come Nube Tossica. L’Azione comprende la dispersione della sostanza e non richiede un tiro per colpire."},{"type":"p","style":"Normal","text":"Il punto d’origine deve essere visibile e materialmente raggiungibile dalla sostanza; ostacoli solidi impediscono di collocarlo oltre di essi.","aggiunta":true},{"type":"p","style":"Normal","text":"Quando la nube compare, le creature già presenti effettuano immediatamente la normale Salvezza. Successivamente effettuano la Salvezza quando entrano nella nube o iniziano il turno al suo interno. Se falliscono, diventano Avvelenate e Accecate secondo le normali regole di Nube Tossica.","aggiunta":true},{"type":"p","style":"Normal","text":"Il raggio massimo dipende dalla Medicina:","aggiunta":true},{"type":"table","rows":[["Medicina","Raggio massimo della nube"],["d20+d4 oppure d20+d6","10 m"],["d20+d8 oppure d20+d10","20 m"],["d20+d12","50 m"],["Saikyō","100 m"]]},{"type":"p","style":"Normal","text":"Se possiedi Tossine Sovrane, usa la Soglia effettiva del veleno dopo l’eventuale sostituzione con la Soglia minima di Prestigio di Medicina. In caso di Salvezza fallita, applichi anche la riduzione dell’Attributo. Gli alleati esposti effettuano normalmente la Salvezza. Profilassi protegge soltanto chi è stato preventivamente trattato contro quella tossina."},{"type":"p","style":"Normal","text":"Si applicano normalmente le regole relative a pareti, ventilazione, acqua, maschere e protezioni respiratorie.","aggiunta":true},{"type":"p","style":"Normal","text":"Saikyō: costo 5 ST, centro entro 100 m, durata 5 turni e raggio massimo 100 m."}],"frequency":"combat"},{"id":"antidoto-perfetto","name":"Antidoto Perfetto","paths":["tossicologo"],"requires":["Maestro Antidoti","Antidoto Istantaneo"],"replaces":["Antidoto Istantaneo"],"action":"reaction","costST":3,"saikyoST":3,"match":"outside","uses":3,"saikyoUses":3,"resource":null,"source":"ruoli","start":86,"end":92,"anchor":"ruoli-antidoto-perfetto","blocks":[{"type":"p","style":"Normal","text":"Prerequisiti: Maestro Antidoti e Antidoto Istantaneo. Attivazione: Reazione. Costo: 3 ST. Limite: 3 utilizzi per combattimento. Portata: un alleato entro 5 m."},{"type":"p","style":"Normal","text":"Somministri una dose di antidoto preparata da te. L’intervento neutralizza tutti i veleni attivi sul bersaglio, rimuove gli stati causati da quelle sostanze e ripristina gli Attributi ridotti dalle tossine."},{"type":"p","style":"Normal","text":"Devi possedere e consumare la dose. I tre utilizzi sostituiscono quello di Antidoto Istantaneo e sono condivisi con la sua forma ordinaria. I PV già persi restano persi."},{"type":"p","style":"Normal","text":"La distanza rappresenta quanto lontano puoi raggiungere il bersaglio con la Reazione. Il percorso deve essere praticabile e devi poter somministrare fisicamente la dose.","aggiunta":true},{"type":"p","style":"Normal","text":"Saikyō: la portata diventa 10 m. Il bersaglio è inoltre immune, per il resto del combattimento, alle tossine appena neutralizzate."}],"frequency":"combat"},{"id":"chirurgia-leggendaria","name":"Chirurgia Leggendaria","paths":["infermeria"],"requires":["Mani da Chirurgo — Maestria"],"replaces":["Mani da Chirurgo — Maestria"],"action":"passive","costST":0,"saikyoST":0,"match":"healing","uses":null,"saikyoUses":null,"resource":null,"source":"ruoli","start":94,"end":105,"anchor":"ruoli-chirurgia-leggendaria","blocks":[{"type":"p","style":"Normal","text":"Evolve: Mani da Chirurgo — Maestria. Tipo: passivo sulle Cure da Campo riuscite."},{"type":"p","style":"Normal","text":"Le tue Cure da Campo restituiscono il doppio dei PV normalmente recuperati. Calcola prima il recupero ordinario, compresi tutti i bonus applicabili, quindi raddoppia il totale."},{"type":"p","style":"Normal","text":"La rimozione di uno Stato negativo rimovibile concessa da Mani da Chirurgo — Maestria diventa la rimozione di due Stati negativi rimovibili."},{"type":"p","style":"Normal","text":"Restano necessari:"},{"type":"p","style":"List Bullet","text":"La normale Prova di Cura da Campo.","aggiunta":true},{"type":"p","style":"List Bullet","text":"I materiali.","aggiunta":true},{"type":"p","style":"List Bullet","text":"L’accesso fisico al paziente.","aggiunta":true},{"type":"p","style":"List Bullet","text":"Il normale limite delle Cure da Campo sullo stesso paziente.","aggiunta":true},{"type":"p","style":"Normal","text":"Mani da Chirurgo — Migliorato continua a determinare il numero di pazienti curabili con una sola Azione.","aggiunta":true},{"type":"p","style":"Normal","text":"Saikyō: il recupero diventa triplo rispetto alla Cura da Campo ordinaria e puoi rimuovere fino a tre Stati negativi rimovibili. La quantità di ST recuperata da altri benefici non viene moltiplicata."}],"frequency":"combat"},{"id":"intervento-prodigioso","name":"Intervento Prodigioso","paths":["infermeria"],"requires":["Intervento Immediato","Specialista in Rianimazione"],"replaces":["Intervento Immediato"],"action":"reaction","costST":3,"saikyoST":3,"match":"outside","uses":3,"saikyoUses":3,"resource":null,"source":"ruoli","start":105,"end":114,"anchor":"ruoli-intervento-prodigioso","blocks":[{"type":"p","style":"Normal","text":"Evolve: Intervento Immediato. Richiede anche: Specialista in Rianimazione. Attivazione: Reazione. Costo: 3 ST. Limite: 3 utilizzi per combattimento. Portata: un alleato entro 10 m."},{"type":"p","style":"Normal","text":"Quando un alleato ancora in vita raggiunge 0 PV, puoi utilizzare la Reazione per raggiungerlo e intervenire immediatamente. Lo spostamento necessario fa parte della Reazione, ma il percorso deve essere praticabile e devi poter raggiungere fisicamente il paziente."},{"type":"p","style":"Normal","text":"Lo Stabilizzi e gli restituisci PV pari al risultato di un tiro completo di Medicina, fino ai suoi PV Massimi. Questo recupero sostituisce l’1d4 di Specialista in Rianimazione e non si somma a esso. Il tiro quantifica il recupero e non costituisce una seconda Prova di riuscita. L’alleato torna cosciente grazie ai PV recuperati."},{"type":"p","style":"Normal","text":"Questa è una rianimazione distinta dalla Cura da Campo:"},{"type":"p","style":"List Bullet","text":"Non consuma il limite delle Cure da Campo sul paziente.","aggiunta":true},{"type":"p","style":"List Bullet","text":"Non riceve il moltiplicatore di Chirurgia Leggendaria.","aggiunta":true},{"type":"p","style":"Normal","text":"I tre utilizzi sostituiscono quello di Intervento Immediato e sono condivisi con la sua forma ordinaria.","aggiunta":true},{"type":"p","style":"Normal","text":"Saikyō: puoi intervenire entro 20 m, mantenendo costo, limite e formula del recupero."}],"frequency":"combat"},{"id":"diagnosi-assoluta","name":"Diagnosi Assoluta","paths":["infermeria"],"requires":["Diagnosi"],"replaces":["Diagnosi"],"action":"bonus","costST":3,"saikyoST":3,"match":"support","uses":null,"saikyoUses":null,"resource":null,"source":"ruoli","start":114,"end":120,"anchor":"ruoli-diagnosi-assoluta","blocks":[{"type":"p","style":"Normal","text":"Evolve: Diagnosi. Attivazione: Azione Bonus. Costo: 3 ST. Bersaglio: un nemico vivente che puoi vedere."},{"type":"p","style":"Normal","text":"Effettui la normale prova di Medicina contro la Difesa Passiva del bersaglio. Se riesci, individui una debolezza del suo corpo e puoi comunicarla ai compagni."},{"type":"p","style":"Normal","text":"Fino all’inizio del tuo secondo turno successivo, gli attacchi che sfruttano concretamente quella debolezza considerano soltanto metà della Riduzione del Danno fissa del bersaglio, arrotondata per difetto. Difesa Passiva, Difesa Attiva e gli altri effetti difensivi continuano ad applicarsi."},{"type":"p","style":"Normal","text":"Puoi avere una sola Diagnosi Assoluta attiva. Resta il Vantaggio ordinario di Diagnosi per il primo alleato che sfrutta la debolezza nello scontro."},{"type":"p","style":"Normal","text":"Saikyō: gli attacchi che sfruttano la debolezza ignorano tutta la Riduzione del Danno fissa, nella stessa finestra di durata. Le altre difese mantengono il proprio funzionamento."}],"frequency":"combat"},{"id":"reazioni-catastrofiche","name":"Reazioni Catastrofiche","paths":["chimico"],"requires":["Reazioni Violente — Maestria"],"replaces":["Reazioni Violente — Maestria"],"action":"passive","costST":0,"saikyoST":0,"match":"preparato","uses":null,"saikyoUses":null,"resource":null,"source":"ruoli","start":122,"end":128,"anchor":"ruoli-reazioni-catastrofiche","blocks":[{"type":"p","style":"Normal","text":"Evolve: Reazioni Violente — Maestria. Tipo: passivo sui preparati offensivi."},{"type":"p","style":"Normal","text":"Il danno iniziale prodotto da un tuo preparato diventa doppio rispetto a quello ordinario, includendo il dado aggiuntivo già concesso da Reazioni Violente — Base."},{"type":"p","style":"Normal","text":"Calcoli il danno una sola volta, applichi il moltiplicatore e poi risolvi le normali difese e riduzioni. Gli stati mantengono il loro funzionamento. Bruciature e altri danni successivi all’impatto iniziale non vengono moltiplicati."},{"type":"p","style":"Normal","text":"Per danno iniziale si intende il Dado Danno registrato nella scheda del preparato, compreso il dado aggiuntivo di Reazioni Violente — Base. Bruciatura e altri danni successivi non fanno parte del danno iniziale e non vengono moltiplicati.","aggiunta":true},{"type":"p","style":"Normal","text":"Saikyō: il danno iniziale diventa triplo rispetto a quello ordinario, sostituendo il raddoppio."}],"frequency":"combat"},{"id":"sintesi-perfetta","name":"Sintesi Perfetta","paths":["chimico"],"requires":["Reagenti Reattivi","Reazioni Violente — Maestria"],"replaces":[],"action":"preparation","costST":0,"saikyoST":0,"match":"outside","uses":null,"saikyoUses":null,"resource":null,"source":"ruoli","start":128,"end":137,"anchor":"ruoli-sintesi-perfetta","blocks":[{"type":"p","style":"Normal","text":"Prerequisiti: Reagenti Reattivi e Reazioni Violente — Maestria. Tipo: passivo durante la preparazione."},{"type":"p","style":"Normal","text":"Entrambi i preparati devono possedere una scheda completa e devono essere effettivamente preparabili dal Chimico.","aggiunta":true},{"type":"p","style":"Normal","text":"Puoi combinare due famiglie differenti di reagenti in una sola dose, utilizzando gli ingredienti richiesti da entrambe. Il composto riceve gli effetti distinti delle due componenti."},{"type":"p","style":"List Bullet","text":"Esplosivo e incendiario: esplosione, Sbilanciato e bruciatura, secondo gli effetti dei preparati utilizzati."},{"type":"p","style":"List Bullet","text":"Acido e fumogeno: corrosione e Accecato, secondo gli effetti dei preparati utilizzati."},{"type":"p","style":"Normal","text":"Per il danno iniziale si utilizza una sola volta quello della componente più potente: i danni completi delle due componenti non vengono sommati. Copie dello stesso stato non si sommano. Ogni componente conserva la propria durata."},{"type":"p","style":"Normal","text":"L’area ordinaria del composto utilizza il raggio minore fra quelli delle componenti. L’uso richiede una sola Azione ordinaria e consuma la dose combinata. Reazioni Catastrofiche si applica al danno iniziale risultante se possiedi quel Talento."},{"type":"p","style":"Normal","text":"Saikyō: puoi combinare tre famiglie differenti nella stessa dose, mantenendo le medesime regole di danno, area e durata."}],"frequency":"combat"},{"id":"dispersione-sovrana","name":"Dispersione Sovrana","paths":["chimico"],"requires":["Lancio Preciso","Reazioni Violente — Migliorato"],"replaces":[],"action":"bonus","costST":3,"saikyoST":3,"match":"preparato","uses":null,"saikyoUses":null,"resource":null,"source":"ruoli","start":137,"end":146,"anchor":"ruoli-dispersione-sovrana","blocks":[{"type":"p","style":"Normal","text":"Prerequisiti: Lancio Preciso e Reazioni Violente — Migliorato. Attivazione: Azione Bonus, prima dell’uso. Costo: 3 ST."},{"type":"p","style":"Normal","text":"Prepari la diffusione di un preparato capace di agire ad area. Per quell’utilizzo puoi scegliere un raggio fino al massimo indicato da Medicina e lanciare il preparato entro 30 m."},{"type":"table","rows":[["Medicina","Raggio massimo totale"],["d20+d4 oppure d20+d6","10 m"],["d20+d8 oppure d20+d10","20 m"],["d20+d12","50 m"],["Saikyō","100 m"]]},{"type":"p","style":"Normal","text":"Questi sono raggi totali, già comprensivi del raddoppio di Reazioni Violente — Migliorato. Lancio Preciso continua a determinare i bersagli che puoi escludere. Danni, stati e Salvezze seguono le regole del preparato."},{"type":"p","style":"Normal","text":"L’Azione Bonus prepara l’effetto: devi comunque utilizzare l’Azione ordinaria per lanciare il preparato e consumare la dose."},{"type":"p","style":"Normal","text":"Si applicano le normali regole di utilizzo dei preparati ad Area. Il punto d’origine deve essere visibile e raggiungibile dal lancio; pareti e ostacoli solidi impediscono di collocarlo oltre di essi. La dose viene consumata normalmente.","aggiunta":true},{"type":"p","style":"Normal","text":"Lancio Preciso continua a permettere di escludere i bersagli previsti. Dispersione Sovrana non modifica il danno o gli Stati del preparato: modifica soltanto la sua capacità di diffusione e la Portata di lancio.","aggiunta":true},{"type":"p","style":"Normal","text":"Saikyō: il raggio massimo è 100 m e puoi lanciare il preparato entro 100 m. Il costo dell’Azione Bonus resta 3 ST."}],"frequency":"combat"},{"id":"progettazione-perfetta","name":"Progettazione Perfetta","paths":["inventore"],"requires":["Inventiva"],"replaces":["Inventiva"],"action":"preparation","costST":0,"saikyoST":0,"match":"outside","uses":null,"saikyoUses":null,"resource":null,"source":"ruoli","start":148,"end":155,"anchor":"ruoli-progettazione-perfetta","blocks":[{"type":"p","style":"Normal","text":"Evolve: Inventiva. Tipo: passivo durante la costruzione."},{"type":"p","style":"Normal","text":"Realizzi i tuoi progetti con un quarto delle ore normalmente richieste e metà dei materiali di lavorazione. Queste riduzioni sostituiscono quelle del Capolavoro per gli stessi valori."},{"type":"p","style":"Normal","text":"La riduzione dei materiali riguarda la lavorazione. I componenti indispensabili del progetto restano necessari: risparmiare metallo non permette di sostituire quattro motori con uno. Strumenti, prova di costruzione e requisiti del progetto mantengono le normali regole."},{"type":"table","rows":[["Meccanica","Tempo rispetto al progetto ordinario","Materiali di lavorazione"],["Prestigi prima di Saikyō","Un quarto","Metà"],["Saikyō","Un decimo","Un quarto"]]},{"type":"p","style":"Normal","text":"L’oggetto mantiene gli effetti del suo progetto. Mente da Inventore — Maestria continua a concedere il proprio normale effetto unico."},{"type":"p","style":"Normal","text":"Esempio: un congegno che richiede 40 ore viene completato in 10 ore, oppure in 4 ore a Saikyō."}],"frequency":"combat"},{"id":"arsenale-da-campo","name":"Arsenale da Campo","paths":["inventore"],"requires":["Prototipo da Campo"],"replaces":["Prototipo da Campo"],"action":"bonus","costST":2,"saikyoST":2,"match":"outside","uses":3,"saikyoUses":5,"resource":null,"source":"ruoli","start":155,"end":161,"anchor":"ruoli-arsenale-da-campo","blocks":[{"type":"p","style":"Normal","text":"Evolve: Prototipo da Campo. Attivazione: Azione Bonus. Costo: 2 ST. Limite: 3 utilizzi per combattimento."},{"type":"p","style":"Normal","text":"Estrai, completi la calibrazione e utilizzi immediatamente un prototipo preparato prima dello scontro. La sua funzione deve essere già definita e devi possedere i componenti necessari."},{"type":"p","style":"Normal","text":"Quando il progetto utilizza un Grado, il prototipo può arrivare fino a d12. Gli eventuali attacchi e le Salvezze si risolvono normalmente. Il prototipo funziona una volta, poi deve essere ricostruito."},{"type":"p","style":"Normal","text":"Puoi preparare dispositivi differenti e scegliere quale impiegare, come un propulsore d’emergenza, una barriera, una rete o una scarica. I tre utilizzi sostituiscono quello di Prototipo da Campo e sono condivisi con la forma ordinaria."},{"type":"p","style":"Normal","text":"Saikyō: disponi di cinque utilizzi per combattimento e i prototipi possono arrivare fino al Grado d20. Il costo resta 2 ST."}],"frequency":"combat"},{"id":"sovraccarico-controllato","name":"Sovraccarico Controllato","paths":["inventore"],"requires":["Sovraccarico"],"replaces":["Sovraccarico"],"action":"bonus","costST":3,"saikyoST":4,"match":"invention","uses":3,"saikyoUses":3,"resource":null,"source":"ruoli","start":161,"end":167,"anchor":"ruoli-sovraccarico-controllato","blocks":[{"type":"p","style":"Normal","text":"Evolve: Sovraccarico. Attivazione: Azione Bonus. Costo: 3 ST. Limite: 3 utilizzi per combattimento."},{"type":"p","style":"Normal","text":"Spingi una tua invenzione oltre il limite e raddoppi un solo valore operativo per il suo prossimo utilizzo entro la fine del turno. Scegli fra i danni prodotti direttamente dal dispositivo, la sua portata o la quantità di danno assorbita da una sua protezione."},{"type":"p","style":"Normal","text":"Dopo l’utilizzo, il congegno rimane inutilizzabile fino all’inizio del tuo turno successivo, poi torna operativo senza dover essere ricostruito."},{"type":"p","style":"Normal","text":"Se è un’arma, moltiplichi soltanto il danno prodotto dai suoi dadi: Attributi, Tecniche e Haki si aggiungono normalmente. Il sovraccarico non moltiplica Azioni, tiri per colpire o Soglie di Salvezza. I normali costi di utilizzo del dispositivo restano necessari."},{"type":"p","style":"Normal","text":"Saikyō: puoi spendere 4 ST per triplicare il valore scelto. Il limite resta tre utilizzi per combattimento e il congegno conserva la stessa finestra di raffreddamento."}],"frequency":"combat"},{"id":"regia-meccanica","name":"Regia Meccanica","paths":["meccanico"],"requires":["Regolazione Fine — Maestria"],"replaces":["Regolazione Fine — Maestria"],"action":"passive","costST":0,"saikyoST":0,"match":"outside","uses":null,"saikyoUses":null,"resource":null,"source":"ruoli","start":169,"end":176,"anchor":"ruoli-regia-meccanica","blocks":[{"type":"p","style":"Normal","text":"Evolve: Regolazione Fine — Maestria. Tipo: passivo."},{"type":"p","style":"Normal","text":"Con una sola Azione puoi gestire quattro macchinari, anziché due. Devi poter raggiungere i loro comandi oppure utilizzare una postazione che li colleghi realmente."},{"type":"p","style":"Normal","text":"Ogni macchina conserva i propri tiri, consumi e munizioni. La seconda attivazione concessa dalla Firma o da Regolazione Fine — Maestria resta applicabile; due effetti che concedono una seconda attivazione allo stesso macchinario non lo portano a quattro."},{"type":"p","style":"Normal","text":"In battaglia navale si tratta delle attivazioni dei sistemi gestiti, non di quattro manovre complete della nave. Il Talento gestisce macchinari e non concede Azioni aggiuntive ai personaggi che li utilizzano o li ospitano."},{"type":"p","style":"Normal","text":"Ogni attivazione aggiuntiva paga separatamente munizioni, carburante, energia e altri consumi del macchinario. Regia Meccanica non rende autonomi i dispositivi e non concede manovre navali ulteriori.","aggiunta":true},{"type":"p","style":"Normal","text":"Saikyō: puoi gestire otto macchinari con la stessa Azione, mantenendo le condizioni descritte."}],"frequency":"combat"},{"id":"ricostruzione-prodigiosa","name":"Ricostruzione Prodigiosa","paths":["meccanico"],"requires":["Pronto Intervento","Carne e Metallo"],"replaces":[],"action":"action","costST":3,"saikyoST":3,"match":"outside","uses":3,"saikyoUses":3,"resource":null,"source":"ruoli","start":176,"end":184,"anchor":"ruoli-ricostruzione-prodigiosa","blocks":[{"type":"p","style":"Normal","text":"Prerequisiti: Pronto Intervento e Carne e Metallo. Attivazione: Azione. Costo: 3 ST. Limite: 3 utilizzi per combattimento."},{"type":"p","style":"Normal","text":"Con attrezzi, ricambi e una Prova di riparazione riuscita puoi intervenire anche su un dispositivo Distrutto, superando il normale limite di Pronto Intervento. Effettui uno dei seguenti interventi:"},{"type":"p","style":"List Bullet","text":"Macchinario: rimetti completamente in funzione un congegno o Modulo danneggiato oppure distrutto, disponendo dei componenti necessari."},{"type":"p","style":"List Bullet","text":"Cyborg ancora in vita: ripristini PV pari alla somma di due tiri completi di Meccanica e rimetti in funzione un suo Modulo danneggiato o distrutto."},{"type":"p","style":"Normal","text":"I PV recuperati non possono superare il massimo. Un Cyborg a 0 PV torna cosciente se l’intervento gli restituisce PV. Questi interventi hanno il proprio limite di tre utilizzi per combattimento."},{"type":"p","style":"Normal","text":"Gli interventi sul corpo e sui Moduli di un Cyborg seguono comunque le definizioni e le condizioni del Manuale del Cyborg.","aggiunta":true},{"type":"p","style":"Normal","text":"Saikyō: il recupero del Cyborg è pari a tre tiri completi di Meccanica e puoi ripristinare due Moduli nello stesso intervento, anziché uno."}],"frequency":"combat"},{"id":"dominio-delle-macchine","name":"Dominio delle Macchine","paths":["meccanico"],"requires":["Sabotaggio Profondo"],"replaces":["Sabotaggio Profondo"],"action":"action","costST":3,"saikyoST":3,"match":"outside","uses":null,"saikyoUses":null,"resource":null,"source":"ruoli","start":184,"end":193,"anchor":"ruoli-dominio-delle-macchine","blocks":[{"type":"p","style":"Normal","text":"Evolve: Sabotaggio Profondo. Attivazione: Azione. Costo: 3 ST. Prova: Meccanica."},{"type":"p","style":"Normal","text":"Raggiungi un punto di comando o un collegamento del sistema e intervieni sui suoi meccanismi. Con una prova riuscita scegli fino a tre macchinari collegati e decidi se:"},{"type":"p","style":"List Bullet","text":"Metterli fuori uso per il resto della battaglia, come Sabotaggio Profondo."},{"type":"p","style":"List Bullet","text":"Prenderne il controllo per il resto della scena."},{"type":"p","style":"Normal","text":"Per utilizzare una macchina conquistata devi spendere l’Azione richiesta e rispettarne munizioni, energia e funzionamento. La manomissione non comprende un’attivazione gratuita dei macchinari."},{"type":"p","style":"Normal","text":"Per recuperare il controllo, un avversario deve raggiungere il sistema, spendere un’Azione e ottenere una prova di Meccanica che eguagli o superi il risultato della tua manomissione."},{"type":"p","style":"Normal","text":"Dominio delle Macchine utilizza le normali regole di accesso fisico stabilite da Sabotaggio: il Meccanico deve poter raggiungere realmente un comando, collegamento o punto di controllo del sistema.","aggiunta":true},{"type":"p","style":"Normal","text":"Saikyō: puoi coinvolgere tutti i macchinari appartenenti allo stesso sistema collegato, come una batteria completa, gli impianti di una nave o una rete di macchine industriali. Resta necessario intervenire realmente sul sistema."}],"frequency":"combat"},{"id":"ricostruzione-leggendaria","name":"Ricostruzione Leggendaria","paths":["carpentiere"],"requires":["Mani sul Legno — Maestria"],"replaces":["Mani sul Legno — Maestria"],"action":"action","costST":3,"saikyoST":3,"match":"outside","uses":3,"saikyoUses":3,"resource":null,"source":"ruoli","start":195,"end":206,"anchor":"ruoli-ricostruzione-leggendaria","blocks":[{"type":"p","style":"Normal","text":"Evolve: Mani sul Legno — Maestria. Attivazione: Azione. Costo: 3 ST. Limite: 3 utilizzi per battaglia navale."},{"type":"p","style":"Normal","text":"Effettui una Riparazione d’Emergenza. Se riesce:"},{"type":"p","style":"List Bullet","text":"Calcola normalmente i PS recuperati.","aggiunta":true},{"type":"p","style":"List Bullet","text":"Aggiungi Mani sul Legno — Base.","aggiunta":true},{"type":"p","style":"List Bullet","text":"Applica l’eventuale raddoppio della Firma La Riparazione che Tiene.","aggiunta":true},{"type":"p","style":"List Bullet","text":"Raddoppia infine il totale ottenuto grazie a Ricostruzione Leggendaria.","aggiunta":true},{"type":"p","style":"Normal","text":"Inoltre puoi rimettere in funzione un Modulo Distrutto, oltre agli effetti già consentiti da Mani sul Legno — Migliorato.","aggiunta":true},{"type":"p","style":"Normal","text":"Servono normalmente i materiali necessari e il recupero non può superare i PS Massimi."},{"type":"p","style":"Normal","text":"Il limite di tre utilizzi è condiviso con il ripristino ordinario di Mani sul Legno — Maestria e sostituisce il precedente limite di una volta."},{"type":"p","style":"Normal","text":"Saikyō: il moltiplicatore finale diventa ×3 e puoi ripristinare due Moduli Distrutti nello stesso intervento."}],"frequency":"naval"},{"id":"nave-leggendaria","name":"Nave Leggendaria","paths":["carpentiere"],"requires":["Nave Cresciuta"],"replaces":[],"action":"preparation","costST":0,"saikyoST":0,"match":"outside","uses":null,"saikyoUses":null,"resource":null,"source":"ruoli","start":206,"end":215,"anchor":"ruoli-nave-leggendaria","blocks":[{"type":"p","style":"Normal","text":"Prerequisito: Nave Cresciuta. Attivazione: completamento di una costruzione o di una ristrutturazione completa in cantiere."},{"type":"p","style":"Normal","text":"La nave sulla quale completi il lavoro ottiene +50% ai PS massimi, arrotondando per eccesso, e due slot Modulo aggiuntivi complessivi, comprendendo quello già concesso da Maestro dei Moduli."},{"type":"p","style":"Normal","text":"Il beneficio si applica una sola volta per nave. Gli slot devono essere riempiti con Moduli realmente costruiti e installati. La capacità della nave non concede Moduli gratuiti."},{"type":"p","style":"Normal","text":"Nave Leggendaria costituisce un miglioramento permanente della nave e segue le normali regole dei Miglioramenti Permanenti. Non si trasferisce su un’altra nave se il Carpentiere cambia equipaggio o imbarcazione.","aggiunta":true},{"type":"p","style":"Normal","text":"Saikyō: il bonus diventa +100% ai PS massimi e gli slot aggiuntivi complessivi diventano tre. Questa forma sostituisce i valori precedenti."},{"type":"table","rows":[["Carpenteria","Aumento dei PS massimi","Slot Modulo aggiuntivi totali"],["Prestigi prima di Saikyō","+50%","2, compreso Maestro dei Moduli"],["Saikyō","+100%","3, compreso Maestro dei Moduli"]]},{"type":"p","style":"Normal","text":"Esempio: una nave che avrebbe 80 PS massimi arriva a 120 PS, oppure a 160 PS a Saikyō."},{"type":"p","style":"Normal","text":"Il lavoro richiede materiali, strumenti e i tempi del progetto, che possono essere giorni o settimane. Barricata conserva il proprio uso ordinario entro 5 m. Ponti enormi, muraglie e fortificazioni richiedono un vero lavoro di costruzione."}],"frequency":"combat"},{"id":"scafo-inespugnabile","name":"Scafo Inespugnabile","paths":["carpentiere"],"requires":["Scafo Rinforzato"],"replaces":["Scafo Rinforzato"],"action":"passive","costST":0,"saikyoST":0,"match":"outside","uses":null,"saikyoUses":null,"resource":null,"source":"ruoli","start":215,"end":221,"anchor":"ruoli-scafo-inespugnabile","blocks":[{"type":"p","style":"Normal","text":"Evolve: Scafo Rinforzato. Tipo: passivo, dopo aver completato i lavori di rinforzo."},{"type":"p","style":"Normal","text":"La nave sulla quale hai realizzato i rinforzi subisce metà dei danni allo Scafo provocati da cannonate, speronamenti e altri impatti fisici, arrotondando per eccesso."},{"type":"p","style":"Normal","text":"Questo beneficio sostituisce la riduzione di un gradino dei Dadi Danno delle cannonate concessa da Scafo Rinforzato."},{"type":"p","style":"Normal","text":"Saikyō: la nave subisce un quarto di quei danni, arrotondando per eccesso, anziché metà."},{"type":"p","style":"Normal","text":"Esempio: una cannonata da 40 PS infligge 20 PS, oppure 10 PS a Saikyō."}],"frequency":"combat"},{"id":"timoniere-leggendario","name":"Timoniere Leggendario","paths":["navigatore"],"requires":["Timoniere Nato — Maestria"],"replaces":["Timoniere Nato — Migliorato","Timoniere Nato — Maestria"],"action":"reaction","costST":3,"saikyoST":3,"match":"outside","uses":3,"saikyoUses":3,"resource":null,"source":"ruoli","start":223,"end":228,"anchor":"ruoli-timoniere-leggendario","blocks":[{"type":"p","style":"Normal","text":"Evolve: Timoniere Nato — Maestria. Attivazione: Reazione. Costo: 3 ST. Limite: 3 utilizzi per battaglia navale."},{"type":"p","style":"Normal","text":"Quando una salva di artiglieria sta per colpire la tua nave, esegui una manovra evasiva e annulli tutti i colpi appartenenti a quella salva. Devi essere al timone e la nave deve essere in grado di manovrare."},{"type":"p","style":"Normal","text":"Attacchi separati richiedono utilizzi separati. Il limite di tre utilizzi è condiviso con Timoniere Nato — Migliorato e sostituisce quello precedente di una volta."},{"type":"p","style":"Normal","text":"Saikyō: dopo aver evitato la salva puoi anche guadagnare o perdere una fascia di distanza, secondo le normali possibilità di movimento della nave. Lo spostamento fa parte della Reazione."}],"frequency":"naval"},{"id":"rotta-sovrana","name":"Rotta Sovrana","paths":["navigatore"],"requires":["Rotta Maestra","Rotta Impossibile"],"replaces":[],"action":"preparation","costST":0,"saikyoST":0,"match":"outside","uses":null,"saikyoUses":null,"resource":null,"source":"ruoli","start":228,"end":234,"anchor":"ruoli-rotta-sovrana","blocks":[{"type":"p","style":"Normal","text":"Prerequisiti: Rotta Maestra e Rotta Impossibile. Tipo: passivo durante la pianificazione della traversata."},{"type":"p","style":"Normal","text":"Quando prepari una traversata verso una destinazione che hai già raggiunto, combini correnti, venti e passaggi per completare il viaggio in metà del tempo ordinario."},{"type":"p","style":"Normal","text":"Restano le normali prove di traversata e gli eventuali pericoli del percorso. Il Talento modifica il tempo del viaggio e non sostituisce il suo svolgimento."},{"type":"p","style":"Normal","text":"Saikyō: il tempo scende a un quarto di quello ordinario, anziché metà."},{"type":"p","style":"Normal","text":"Esempio: una traversata normalmente lunga otto giorni richiede quattro giorni, oppure due giorni a Saikyō."}],"frequency":"combat"},{"id":"cartografia-leggendaria","name":"Cartografia Leggendaria","paths":["navigatore"],"requires":["Cartografo"],"replaces":["Cartografo"],"action":"preparation","costST":0,"saikyoST":0,"match":"outside","uses":null,"saikyoUses":null,"resource":null,"source":"ruoli","start":234,"end":240,"anchor":"ruoli-cartografia-leggendaria","blocks":[{"type":"p","style":"Normal","text":"Evolve: Cartografo. Tipo: passivo durante la realizzazione delle carte."},{"type":"p","style":"Normal","text":"Le carte nautiche che realizzi concedono come bonus un tiro completo del tuo dado Navigazione, sostituendo il normale +d8 di Cartografo. Il dado viene registrato quando completi la carta."},{"type":"table","rows":[["Navigazione alla realizzazione","Bonus della carta"],["d20+d4","+d20+d4"],["d20+d6","+d20+d6"],["d20+d8","+d20+d8"],["d20+d10","+d20+d10"],["d20+d12","+d20+d12"],["Saikyō","+d20+d20"]]},{"type":"p","style":"Normal","text":"Il beneficio vale per le prove che utilizzano effettivamente quella carta e può essere sfruttato anche da un altro navigatore."},{"type":"p","style":"Normal","text":"Una carta già completata mantiene il proprio dado. Per migliorarla devi aggiornarla attraverso un nuovo lavoro cartografico. A Saikyō una carta realizzata o aggiornata da te concede +d20+d20."}],"frequency":"combat"},{"id":"lettura-assoluta","name":"Lettura Assoluta","paths":["archeologo"],"requires":["Scrittura Morta — Maestria"],"replaces":["Scrittura Morta — Maestria"],"action":"passive","costST":0,"saikyoST":0,"match":"outside","uses":null,"saikyoUses":null,"resource":null,"source":"ruoli","start":242,"end":247,"anchor":"ruoli-lettura-assoluta","blocks":[{"type":"p","style":"Normal","text":"Evolve: Scrittura Morta — Maestria. Tipo: passivo."},{"type":"p","style":"Normal","text":"Quando riesci in una prova di traduzione ottieni la traduzione completa e il dettaglio nascosto previsto dalla Firma, anche senza raggiungere il margine +4."},{"type":"p","style":"Normal","text":"Per studiare una singola iscrizione o stele leggibile, compreso un Poneglyph, ti serve al massimo un’ora. Se il lavoro richiederebbe normalmente meno tempo, resta quello inferiore. Archivi e testi composti da molte iscrizioni richiedono lo studio delle singole parti."},{"type":"p","style":"Normal","text":"Saikyō: il tempo massimo per una singola iscrizione scende a dieci minuti."}],"frequency":"combat"},{"id":"archivio-vivente","name":"Archivio Vivente","paths":["archeologo"],"requires":["Memoria del Mondo"],"replaces":["Memoria del Mondo"],"action":"preparation","costST":0,"saikyoST":0,"match":"outside","uses":1,"saikyoUses":1,"resource":null,"source":"ruoli","start":247,"end":256,"anchor":"ruoli-archivio-vivente","blocks":[{"type":"p","style":"Normal","text":"Evolve: Memoria del Mondo. Attivazione: cinque minuti di esame. Limite: una volta per scena."},{"type":"p","style":"Normal","text":"Esaminando un luogo antico, un reperto o una struttura puoi ottenere risposte concrete a due delle seguenti domande, a tua scelta:"},{"type":"p","style":"List Bullet","text":"Qual era la sua funzione originaria?"},{"type":"p","style":"List Bullet","text":"Quale pericolo o difesa è documentato dalle testimonianze presenti?"},{"type":"p","style":"List Bullet","text":"Qual è il modo corretto di accedervi, utilizzarlo o disattivarlo?"},{"type":"p","style":"Normal","text":"Le risposte derivano dalla storia del soggetto e dalle tracce conservate: iscrizioni, architettura, simboli, materiali e conoscenze già acquisite. Sono informazioni utilizzabili nell’esplorazione."},{"type":"p","style":"Normal","text":"Puoi scoprire, per esempio, che una sala era destinata alle esecuzioni, che il pavimento aziona un contrappeso o che una porta si apre attraverso un preciso ordine di simboli."},{"type":"p","style":"Normal","text":"Saikyō: ottieni risposta a tutte e tre le domande nello stesso esame, mantenendo tempo e limite descritti."}],"frequency":"scene"},{"id":"maestro-dei-meccanismi-antichi","name":"Maestro dei Meccanismi Antichi","paths":["archeologo"],"requires":["Meccanismi Antichi","Trappola Antica"],"replaces":[],"action":"reaction","costST":2,"saikyoST":2,"match":"outside","uses":3,"saikyoUses":3,"resource":null,"source":"ruoli","start":256,"end":262,"anchor":"ruoli-maestro-dei-meccanismi-antichi","blocks":[{"type":"p","style":"Normal","text":"Prerequisiti: Meccanismi Antichi e Trappola Antica. Attivazione: Reazione. Costo: 2 ST. Limite: 3 utilizzi per combattimento."},{"type":"p","style":"Normal","text":"Quando una creatura raggiunge il punto d’attivazione di una trappola, oppure un meccanismo antico sta per scattare, puoi intervenire immediatamente per attivarlo, bloccarne l’attivazione o invertirne il funzionamento, se il dispositivo lo permette."},{"type":"p","style":"Normal","text":"Devi aver identificato il meccanismo e poter raggiungere il comando o un collegamento utilizzabile, come una leva, una fune, un innesco o un pannello. Si applicano gli effetti, i danni e le Salvezze già previsti dal dispositivo."},{"type":"p","style":"Normal","text":"Saikyō: puoi azionare due meccanismi collegati con la stessa Reazione, pagando una sola volta il costo e consumando un solo utilizzo."},{"type":"p","style":"Normal","text":"Puoi così chiudere una porta mentre attivi la trappola davanti a essa oppure arrestare un contrappeso e aprire il passaggio che libera."}],"frequency":"combat"},{"id":"nutrimento-leggendario","name":"Nutrimento Leggendario","paths":["cuoco"],"requires":["Mano del Cuoco — Maestria"],"replaces":["Mano del Cuoco — Maestria"],"action":"passive","costST":0,"saikyoST":0,"match":"outside","uses":null,"saikyoUses":null,"resource":null,"source":"ruoli","start":264,"end":271,"anchor":"ruoli-nutrimento-leggendario","blocks":[{"type":"p","style":"Normal","text":"Evolve: Mano del Cuoco — Maestria. Tipo: passivo sui piatti ordinari."},{"type":"p","style":"Normal","text":"I tuoi piatti restituiscono il doppio dei PV e della ST normalmente recuperati. Calcoli prima il recupero ordinario, compresi Mano del Cuoco — Base e gli ingredienti utilizzati, poi raddoppi il risultato."},{"type":"p","style":"Normal","text":"Se il piatto recupera entrambe le risorse, Nutrimento Leggendario moltiplica entrambe. Non aggiunge una risorsa che la ricetta non recupera.","aggiunta":true},{"type":"p","style":"Normal","text":"I tuoi piatti rimuovono inoltre fino a due Stati negativi rimovibili, anziché quello previsto da Mano del Cuoco — Maestria. Ogni piatto continua a recuperare soltanto le risorse previste dalla propria ricetta e conserva il normale numero di destinatari."},{"type":"p","style":"Normal","text":"Saikyō: il recupero diventa triplo rispetto al piatto ordinario e gli Stati negativi rimovibili diventano tre."},{"type":"p","style":"Normal","text":"Esempio: un piatto che normalmente restituisce 12 PV e 4 ST ne restituisce 24 e 8, oppure 36 e 12 a Saikyō."}],"frequency":"combat"},{"id":"servizio-sovrano","name":"Servizio Sovrano","paths":["cuoco"],"requires":["Servizio in Battaglia"],"replaces":["Servizio in Battaglia"],"action":"bonus","costST":3,"saikyoST":4,"match":"outside","uses":null,"saikyoUses":null,"resource":null,"source":"ruoli","start":271,"end":276,"anchor":"ruoli-servizio-sovrano","blocks":[{"type":"p","style":"Normal","text":"Evolve: Servizio in Battaglia. Attivazione: Azione Bonus. Costo: 3 ST. Bersagli: fino a tre personaggi coscienti entro 10 m, compreso eventualmente te stesso."},{"type":"p","style":"Normal","text":"Servi porzioni già preparate. I destinatari consumano immediatamente il cibo e ricevono gli effetti del piatto senza spendere un’Azione."},{"type":"p","style":"Normal","text":"Devi possedere porzioni sufficienti e consumi quelle effettivamente servite. Mano del Cuoco — Migliorato continua a determinare quante persone può nutrire una preparazione. Nutrimento Leggendario si applica se possiedi quel Talento."},{"type":"p","style":"Normal","text":"Saikyō: spendendo 4 ST, servi fino a cinque personaggi coscienti entro 20 m. La preparazione dei piatti avviene prima dello scontro."}],"frequency":"combat"},{"id":"secondo-fuoco-leggendario","name":"Secondo Fuoco Leggendario","paths":["cuoco"],"requires":["Secondo Fuoco"],"replaces":["Secondo Fuoco"],"action":"reaction","costST":2,"saikyoST":2,"match":"outside","uses":3,"saikyoUses":3,"resource":null,"source":"ruoli","start":276,"end":281,"anchor":"ruoli-secondo-fuoco-leggendario","blocks":[{"type":"p","style":"Normal","text":"Evolve: Secondo Fuoco. Attivazione: Reazione. Costo: 2 ST. Limite: 3 utilizzi per combattimento. Portata: un compagno cosciente entro 10 m."},{"type":"p","style":"Normal","text":"Quando il compagno scende sotto metà dei propri PV puoi servirgli immediatamente una porzione già preparata. Il destinatario riceve gli effetti completi del piatto, sostituendo il normale recupero di 1d6 ST di Secondo Fuoco."},{"type":"p","style":"Normal","text":"La porzione viene consumata. Se possiedi Nutrimento Leggendario, si applicano anche i suoi benefici. I tre utilizzi sostituiscono quello ordinario di una volta per scontro e sono condivisi con la forma base."},{"type":"p","style":"Normal","text":"Saikyō: la portata diventa 20 m e puoi intervenire quando il compagno subisce danni, anche se rimane sopra metà dei propri PV. Deve essere ancora cosciente e in grado di consumare la porzione. Costo e limite restano quelli descritti."}],"frequency":"combat"},{"id":"volonta-indomabile","name":"Volontà Indomabile","paths":["spirito"],"requires":[],"replaces":[],"action":"passive","costST":0,"saikyoST":0,"match":"spirit","uses":null,"saikyoUses":null,"resource":null,"source":"haki","start":39,"end":45,"anchor":"haki-volonta-indomabile","blocks":[{"type":"p","style":"Normal","text":"Tipo: passivo. Costo: nessuno. Attivazione: automatica nei tiri pertinenti."},{"type":"p","style":"Normal","text":"Quando una regola richiede un tiro di Spirito per resistere a paura, intimidazione o coercizione mentale, il d20 di Spirito vale automaticamente 20. Si tira normalmente il dado aggiuntivo di Prestigio e l’eventuale Skill applicabile."},{"type":"p","style":"Normal","text":"Con Spirito d20+d8, il contributo dell’Attributo diventa quindi 20+d8. A Spirito Saikyō, anche il secondo d20 vale 20: il contributo di Spirito è 40, prima dell’eventuale Skill o degli altri modificatori consentiti."},{"type":"p","style":"Normal","text":"Il risultato viene comunque confrontato con la difficoltà o il tiro contrapposto richiesto. Il potenziamento non garantisce il successo e non modifica i tiri per colpire o i danni."},{"type":"p","style":"Normal","text":"Volontà Indomabile si applica soltanto quando l’effetto prevede effettivamente una prova di Spirito. Non crea una nuova prova contro effetti automatici. In particolare, non permette da sola di annullare Pressione Imperiale."}],"frequency":"combat"},{"id":"sintonia-dei-colori","name":"Sintonia dei Colori","paths":["spirito"],"requires":[],"replaces":[],"action":"bonus","costST":0,"saikyoST":0,"match":"spirit","uses":null,"saikyoUses":null,"resource":null,"source":"haki","start":45,"end":50,"anchor":"haki-sintonia-dei-colori","blocks":[{"type":"p","style":"Normal","text":"Tipo: attivo. Attivazione: un’Azione Bonus. Costo: 1 PIP per ciascun Colore attivato."},{"type":"p","style":"Normal","text":"Con una sola Azione Bonus puoi attivare due Colori dell’Haki che possiedi. A Spirito Saikyō puoi attivarne tre. Ogni Colore paga il proprio PIP dalla propria riserva."},{"type":"p","style":"Normal","text":"Armamento e Osservazione, per esempio, si accendono insieme pagando 1 PIP di Armamento e 1 di Osservazione. A Saikyō puoi aggiungere il Re soltanto se il personaggio lo possiede e dispone del PIP necessario."},{"type":"p","style":"Normal","text":"Sintonia non riduce i costi, non conferisce nuovi Colori e non attiva insieme anche Armatura Totale, Anticipo, Rivestimento o altri effetti attivi. Ogni Colore mantiene inoltre i propri costi ordinari di mantenimento."}],"frequency":"combat"},{"id":"riscossa-della-volonta","name":"Riscossa della Volontà","paths":["spirito"],"requires":[],"replaces":[],"action":"bonus","costST":0,"saikyoST":0,"match":"spirit","uses":null,"saikyoUses":null,"resource":null,"source":"haki","start":50,"end":57,"anchor":"haki-riscossa-della-volonta","blocks":[{"type":"p","style":"Normal","text":"Tipo: attivo. Attivazione: un’Azione Bonus. Costo: 0 Stamina. Limite: una volta, poi serve un riposo breve o lungo per poterla usare di nuovo."},{"type":"p","style":"Normal","text":"Richiami la tua determinazione e recuperi un numero di PIP determinato dal dado completo di Spirito. Il recupero è un unico totale da distribuire liberamente fra Armamento, Osservazione e Re, limitatamente ai Colori che possiedi."},{"type":"table","rows":[["Dado di Spirito","PIP totali recuperabili"],["d20+d4","1"],["d20+d6","2"],["d20+d8","3"],["d20+d10","4"],["d20+d12","5"],["d20+d20","6"]]},{"type":"p","style":"Normal","text":"Nessuna riserva può superare il proprio massimo. I PIP che non trovano spazio vengono persi: non si conservano per dopo e non aumentano la capacità dei Colori."},{"type":"p","style":"Normal","text":"Puoi usare Riscossa anche con tutte le riserve a zero o con i Colori spenti. Il recupero non accende automaticamente alcun Colore e non ripristina gli usi di capacità limitate a una volta per combattimento."},{"type":"p","style":"Normal","text":"Esempio: con Spirito d20+d12 recuperi fino a 5 PIP complessivi. Puoi assegnarne 2 ad Armamento, 2 a Osservazione e 1 al Re, se in ciascuna riserva c’è spazio. Non recuperi 5 PIP per ogni Colore."}],"frequency":"combat"}],"haki":[{"id":"armatura-totale-superiore","name":"Armatura Totale Superiore","color":0,"level":1,"cost":2,"saikyoCost":3,"duration":1,"saikyoDuration":2,"match":"defense","group":"d8","source":"haki","start":61,"end":68,"anchor":"haki-armatura-totale-superiore","blocks":[{"type":"p","style":"Normal","text":"Evolve: Armatura Totale. Sblocco: Armamento d20+d4. Attivazione: un’Azione Bonus, con Armamento già attivo."},{"type":"p","style":"Normal","text":"Pagando 2 PIP di Armamento, dimezzi i danni di tutti gli attacchi ricevuti fino all’inizio del tuo turno successivo. La protezione vale per ogni attacco nella finestra, compresi quelli dotati di Haki."},{"type":"p","style":"Normal","text":"A Saikyō, puoi pagare 3 PIP per mantenere la stessa protezione per 2 turni: dall’attivazione fino all’inizio del tuo secondo turno successivo."},{"type":"p","style":"Normal","text":"Per ciascun attacco che supera le difese, dimezza il danno con arrotondamento per eccesso, poi applica le consuete riduzioni. Le normali difese restano utilizzabili. La protezione non copre automaticamente fonti che non sono attacchi, come una caduta o un pericolo ambientale."},{"type":"p","style":"Normal","text":"Armatura Totale base e Superiore non dimezzano due volte lo stesso attacco. La versione base resta utilizzabile a 1 PIP per proteggersi da un singolo attacco, nei termini del regolamento ordinario."},{"type":"p","style":"Normal","text":"Esempio: due attacchi infliggono rispettivamente 31 e 18 danni prima delle riduzioni. Con Armatura Totale Superiore diventano 16 e 9; si applica poi la Riduzione del Danno pertinente a ciascuno."}]},{"id":"esplosione-haki-superiore","name":"Esplosione Haki Superiore","color":0,"level":3,"cost":2,"saikyoCost":3,"duration":0,"saikyoDuration":0,"match":"attack","group":"d10","source":"haki","start":68,"end":79,"anchor":"haki-esplosione-haki-superiore","blocks":[{"type":"p","style":"Normal","text":"Evolve: Esplosione Haki. Sblocco: Armamento d20+d8. Attivazione: un’Azione Bonus, prima di un tuo attacco fisico e con Armamento già attivo."},{"type":"p","style":"Normal","text":"Prepari un’esplosione di Armamento che si sprigiona dal punto raggiunto dall’attacco. La sua ampiezza cresce con il dado di Armamento."},{"type":"table","rows":[["Dado di Armamento","Raggio dell’esplosione","Costo"],["d20+d8","20 m","2 PIP"],["d20+d10","30 m","2 PIP"],["d20+d12","50 m","2 PIP"],["d20+d20","100 m","3 PIP"]]},{"type":"p","style":"Normal","text":"Il bersaglio principale risolve soltanto l’attacco originario: non riceve una seconda copia del danno dall’esplosione. I nemici secondari nel raggio vengono coinvolti dall’onda e possono difendersi contro lo stesso tiro per colpire dell’attacco originario, usando le difese compatibili e le risorse normalmente disponibili."},{"type":"p","style":"Normal","text":"Se non riescono a difendersi, subiscono metà del danno dell’attacco pertinente all’esplosione, arrotondata per difetto, prima della propria Riduzione del Danno. Il colpo originario può quindi essere parato dal bersaglio principale e avere comunque conseguenze per un altro nemico che fallisce la propria difesa. L’esplosione non dà un secondo tentativo di colpire il bersaglio principale."},{"type":"p","style":"Normal","text":"Il centro dell’esplosione deve essere un punto realmente raggiunto dall’attacco entro la sua normale portata. Il raggio dell’onda non allunga la portata dell’arma o della Tecnica e non concede un attacco supplementare."},{"type":"p","style":"Normal","text":"Nell’onda si usa il danno dell’attacco, con i contributi normalmente applicabili, ma non si propagano automaticamente effetti destinati al solo bersaglio principale. Proiezione, Schianto e condizioni della Tecnica rivolte soltanto al bersaglio principale non vengono copiati sui bersagli secondari. Ryou modifica invece il danno totale dell’attacco secondo la propria regola generale: il riferimento al colpo dall’interno è narrativo e non identifica una componente numerica separata."},{"type":"p","style":"Normal","text":"La scala di distruzione ambientale legata a Forza resta una regola distinta. Non aumenta il raggio dell’Esplosione Haki e non aggiunge una seconda copia dei danni dell’esplosione agli stessi personaggi."},{"type":"p","style":"Normal","text":"La versione base resta disponibile a 1 PIP, con il suo raggio ordinario di 5 m."},{"type":"p","style":"Normal","text":"Esempio: l’attacco produce 40 danni pertinenti all’esplosione. Il bersaglio principale risolve quei 40 danni secondo le difese ordinarie. Un nemico secondario che fallisce la difesa risolve 20 danni, poi applica la propria Riduzione del Danno. Un successivo Schianto del bersaglio principale non aumenta questi 20 danni."}]},{"id":"ryou-persistente","name":"Ryou Persistente","color":0,"level":5,"cost":4,"saikyoCost":5,"duration":2,"saikyoDuration":3,"match":"physical","group":"d20","source":"haki","start":79,"end":86,"anchor":"haki-ryou-persistente","blocks":[{"type":"p","style":"Normal","text":"Evolve: Ryou. Sblocco: Armamento d20+d12. Attivazione: un’Azione Bonus, con Armamento già attivo."},{"type":"p","style":"Normal","text":"Pagando 4 PIP di Armamento, mantieni il Ryou per 2 turni. Durante ciascuno dei tuoi turni compresi nella durata, puoi applicare il Ryou a un solo attacco fisico. Scegli l’attacco prima di effettuare il tiro per colpire."},{"type":"p","style":"Normal","text":"A Saikyō, puoi pagare 5 PIP per una durata di 3 turni, mantenendo il limite di un attacco fisico per tuo turno."},{"type":"p","style":"Normal","text":"Il Ryou conserva il funzionamento ordinario: calcoli normalmente il danno totale dell’attacco scelto, comprendendo tutti i dadi e i bonus effettivamente applicabili, e lo moltiplichi ×2 una sola volta. Non raddoppiare separatamente le singole componenti per poi moltiplicare nuovamente il risultato. Il riferimento al colpo che agisce dall’interno rimane descrittivo e non crea una categoria meccanica o una componente di danno separata. Ryou non rende il colpo automatico e non impedisce al bersaglio di utilizzare Difesa Passiva, Difesa Attiva, Riduzione del Danno o altre difese normalmente consentite, salvo una regola specifica."},{"type":"p","style":"Normal","text":"Gli attacchi richiedono le proprie Azioni e gli eventuali costi della Tecnica. Un attacco mancato consuma l’applicazione scelta per quel turno e non concede un secondo tentativo. Il potenziamento Ryou Persistente non aggiunge attacchi, non si applica automaticamente a ogni colpo di una Raffica e termina se Armamento viene interrotto."},{"type":"p","style":"Normal","text":"La versione base resta disponibile a 3 PIP per il singolo attacco previsto dal regolamento. Nei turni successivi all’attivazione di Ryou Persistente puoi impiegare l’Azione Bonus per un Talento compatibile, perché il Ryou sta già durando; devi comunque disporre delle risorse richieste dal Talento."}]},{"id":"anticipo-superiore","name":"Anticipo Superiore","color":1,"level":1,"cost":2,"saikyoCost":2,"duration":1,"saikyoDuration":1,"match":"counter","group":"d8","source":"haki","start":93,"end":99,"anchor":"haki-anticipo-superiore","blocks":[{"type":"p","style":"Normal","text":"Evolve: Anticipo. Sblocco: Osservazione d20+d4. Costo: 2 PIP di Osservazione. Attivazione: un’Azione Bonus, con Osservazione già attiva."},{"type":"p","style":"Normal","text":"Prepari una lettura del prossimo movimento avversario. Fino all’inizio del tuo turno successivo puoi aggiungere tre tiri completi di Haki dell’Osservazione a un solo tiro difensivo compatibile, effettuato per una Schivata oppure per una Difesa Attiva eseguita con una Tecnica d’attacco."},{"type":"p","style":"Normal","text":"Con Osservazione d20+d8 aggiungi tre tiri separati di d20+d8. A Saikyō restano tre tiri, ciascuno di d20+d20, e il costo resta 2 PIP. La crescita deriva dal dado completo del Colore."},{"type":"p","style":"Normal","text":"Devi dichiarare l’impiego sul tiro scelto prima di tirare. La difesa consuma normalmente la Reazione e le altre risorse richieste, inclusi i costi della Tecnica. Anticipo Superiore non concede Reazioni aggiuntive, non aumenta il danno e non permette danni in risposta senza una capacità specifica come Contraccolpo: questa infligge il normale Dado Danno soltanto se la difesa supera il tiro avversario; un pareggio difende ma non infligge quel danno."},{"type":"p","style":"Normal","text":"La versione base resta disponibile a 1 PIP, con i suoi due tiri di Osservazione. Base e Superiore non si sommano sullo stesso tiro."}]},{"id":"previsione-breve-prolungata","name":"Previsione Breve Prolungata","color":1,"level":3,"cost":2,"saikyoCost":3,"duration":2,"saikyoDuration":3,"match":"defense","group":"d12","source":"haki","start":99,"end":104,"anchor":"haki-previsione-breve-prolungata","blocks":[{"type":"p","style":"Normal","text":"Evolve: Previsione Breve. Sblocco: Osservazione d20+d8. Attivazione: un’Azione Bonus, con Osservazione già attiva."},{"type":"p","style":"Normal","text":"Pagando 2 PIP di Osservazione, prolunghi la Previsione Breve per 2 turni. Durante la durata conservi la sua protezione ordinaria: gli attacchi fisici normali non riescono a colpirti. Gli attacchi dotati di Haki e gli effetti ad area restano efficaci e si risolvono normalmente."},{"type":"p","style":"Normal","text":"A Saikyō, puoi pagare 3 PIP per una durata di 3 turni. Non si amplia il tipo di protezione: cresce la durata, mentre Haki ed effetti ad area restano in grado di raggiungerti."},{"type":"p","style":"Normal","text":"La capacità non rende immuni a cadute, crolli, condizioni o altri pericoli estranei alla protezione descritta. Termina se Osservazione viene interrotta. La versione base resta disponibile a 2 PIP per 1 turno."}]},{"id":"anticipo-offensivo","name":"Anticipo Offensivo","color":1,"level":5,"cost":2,"saikyoCost":3,"duration":0,"saikyoDuration":0,"match":"physical","group":"offensive","source":"haki","start":104,"end":110,"anchor":"haki-anticipo-offensivo","blocks":[{"type":"p","style":"Normal","text":"Sblocco: Osservazione d20+d12. Attivazione: un’Azione Bonus, prima di un tuo attacco fisico e con Osservazione già attiva."},{"type":"p","style":"Normal","text":"Pagando 2 PIP di Osservazione, aggiungi due tiri completi di Haki dell’Osservazione al tiro per colpire di un solo tuo attacco fisico. Leggi l’apertura dell’avversario e scegli il momento esatto in cui attaccare."},{"type":"p","style":"Normal","text":"A Saikyō, puoi pagare 3 PIP per aggiungere tre tiri completi di Osservazione allo stesso tiro per colpire."},{"type":"p","style":"Normal","text":"Il bonus modifica soltanto la precisione dell’attacco: non aggiunge danni e non garantisce di colpire. Le normali difese restano disponibili. Un eventuale Colpo Pulito dipende comunque dalle regole ordinarie e dal margine effettivamente ottenuto."},{"type":"p","style":"Normal","text":"L’attacco richiede la propria Azione e gli eventuali costi della Tecnica. Un effetto con più attacchi separati beneficia del bonus soltanto sull’attacco scelto. Anticipo Offensivo non concede attacchi supplementari e non si somma ad Anticipo difensivo sullo stesso tiro."}]},{"id":"pressione-imperiale","name":"Pressione Imperiale","color":2,"level":1,"cost":2,"saikyoCost":2,"duration":0,"saikyoDuration":0,"match":"any","group":"2","source":"haki","start":119,"end":129,"anchor":"haki-prestigio-i-pressione-imperiale","blocks":[{"type":"p","style":"Normal","text":"Evolve: Grido dell’Imperatore. Costo: 2 PIP del Re. Attivazione: un’Azione Bonus, con il Re già attivo. Limite: una volta per combattimento."},{"type":"p","style":"Normal","text":"Concentri la pressione del tuo Haki su un nemico che percepisci entro la portata disponibile. Il bersaglio può essere anche un boss. La capacità non infligge danni diretti."},{"type":"p","style":"Normal","text":"Il bersaglio perde la sua prossima Azione. Interrompe inoltre tutti i suoi Colori dell’Haki attivi, compresi gli effetti in corso, e le Tecniche che sta mantenendo. Non può riattivare quei Colori fino alla fine del suo secondo turno successivo all’applicazione."},{"type":"table","rows":[["Prestigio del Re posseduto","Portata massima"],["I","100 m"],["II","500 m"],["Saikyō","1.000 m"]]},{"type":"p","style":"Normal","text":"La portata indica quanto lontano puoi raggiungere il singolo bersaglio. Non è un raggio che coinvolge tutti i nemici. Devi realmente percepirlo, attraverso la vista o un’altra percezione già disponibile al personaggio. Pressione Imperiale non rivela automaticamente la posizione di un nemico sconosciuto."},{"type":"p","style":"Normal","text":"La perdita riguarda un’Azione: non cancella automaticamente tutto il turno, il Movimento, l’Azione Bonus o le Reazioni. Le capacità innate e i poteri non mantenuti seguono le proprie regole; l’effetto non annulla indiscriminatamente Frutti del Diavolo o tratti razziali."},{"type":"p","style":"Normal","text":"Non viene introdotto un tiro di paura o di Spirito per resistere: si mantiene la natura dell’effetto del Grido. Volontà Indomabile non crea una prova che l’effetto non prevede."},{"type":"p","style":"Normal","text":"Pressione Imperiale e Grido dell’Imperatore base condividono lo stesso utilizzo per combattimento. Puoi scegliere il Grido base a 1 PIP, ma dopo aver usato una delle due forme non puoi usare l’altra nello stesso combattimento. Riscossa della Volontà recupera PIP e non ripristina questo utilizzo."},{"type":"p","style":"Normal","text":"Esempio di durata: colpisci un nemico prima del suo turno. Nel primo turno successivo perde l’Azione e non può riattivare i Colori interrotti. Nel secondo turno successivo conserva la propria Azione, ma il blocco dell’Haki resta fino alla fine di quel turno. Dal terzo può tornare ad attivarli pagando i costi ordinari."}]},{"id":"impatto-sovrano","name":"Impatto Sovrano","color":2,"level":2,"cost":3,"saikyoCost":3,"duration":0,"saikyoDuration":0,"match":"physical","group":"3","source":"haki","start":129,"end":136,"anchor":"haki-prestigio-ii-impatto-sovrano","blocks":[{"type":"p","style":"Normal","text":"Evolve: Rivestimento del Re. Costo: 3 PIP del Re. Attivazione: un’Azione Bonus, prima di un tuo attacco fisico e con il Re già attivo."},{"type":"p","style":"Normal","text":"Scegli un solo attacco fisico. I Dadi Danno previsti per quell’attacco valgono automaticamente il loro risultato massimo, come nel Rivestimento ordinario. Con Impatto Sovrano, raddoppi poi il totale di quei Dadi Danno massimizzati."},{"type":"p","style":"Normal","text":"Se l’attacco ha 3d20 di Dadi Danno, il loro massimo è 60 e Impatto Sovrano porta questo componente a 120. Si aggiungono poi gli altri componenti dell’attacco secondo le rispettive regole."},{"type":"p","style":"Normal","text":"I tiri di Attributo, Skill e Haki e i bonus fissi non vengono automaticamente massimizzati o raddoppiati. Non si aggiunge un nuovo tiro di Spirito ai danni per il solo possesso del Re."},{"type":"p","style":"Normal","text":"Il tiro per colpire resta necessario. Difesa Passiva, Difesa Attiva e Riduzione del Danno continuano a funzionare normalmente. L’attacco richiede la propria Azione e gli eventuali costi della Tecnica. L’effetto si applica soltanto all’attacco scelto, anche se la capacità usata prevede una Raffica o più attacchi distinti."},{"type":"p","style":"Normal","text":"Il Rivestimento del Re base resta disponibile a 2 PIP e massimizza i DD senza raddoppiarli. Il costo di 3 PIP di Impatto Sovrano sostituisce quello base: non si pagano 2 PIP più 3 PIP."}]},{"id":"volonta-illeggibile","name":"Volontà Illeggibile","color":2,"level":3,"cost":3,"saikyoCost":3,"duration":0,"saikyoDuration":0,"match":"physical","group":"3","source":"haki","start":136,"end":143,"anchor":"haki-saikyo-volonta-illeggibile","blocks":[{"type":"p","style":"Normal","text":"Completa: lo stesso Rivestimento del Re evoluto da Impatto Sovrano. Costo: sempre 3 PIP del Re complessivi. Attivazione: la stessa Azione Bonus che prepara il singolo attacco."},{"type":"p","style":"Normal","text":"Quando usi il Rivestimento evoluto, conservi i Dadi Danno massimizzati e raddoppiati di Impatto Sovrano. In aggiunta, il bersaglio non può applicare i benefici difensivi attivi dell’Haki dell’Osservazione contro quell’attacco."},{"type":"p","style":"Normal","text":"Anticipo e Anticipo Superiore non aggiungono dadi alla difesa contro quel colpo. Previsione Futura non permette di schivarlo automaticamente. La stessa esclusione vale per gli altri benefici difensivi attivi di Osservazione pertinenti a quell’attacco."},{"type":"p","style":"Normal","text":"Il bersaglio può comunque usare Schivata, Parata e altre difese fisiche compatibili, con i propri tiri e le proprie risorse. Il colpo non è automatico. I passivi di percezione di Osservazione rimangono, e gli effetti attivi del bersaglio continuano a valere contro gli altri attacchi se non vengono interrotti da una regola distinta."},{"type":"p","style":"Normal","text":"Volontà Illeggibile non spegne permanentemente Osservazione e non è un passivo sempre presente sui tuoi attacchi: si applica soltanto al singolo attacco rivestito per cui hai pagato il costo."},{"type":"p","style":"Normal","text":"Non si pagano due effetti separati. A Saikyō, una sola Azione Bonus e 3 PIP totali producono il Rivestimento con entrambi i benefici: DD massimizzati e raddoppiati, più esclusione dell’anticipazione difensiva attiva di Osservazione contro quel colpo."}]}],"scales":{"destruction":[5,10,30,100,300,1000],"projection":[10,15,20,30,50,100],"movement":[10,15,20,30,100,1000],"jump":[5,10,15,20,50,200],"slash":[20,30,50,100,300,1000],"cut":[5,10,30,100,300,1000],"range":[100,150,200,300,1000,5000],"deviations":[1,1,2,2,3,5]},"attributes":{"Forza":{"source":"combattenti","start":13,"end":85,"anchor":"combattenti-prestigio-di-forza","blocks":[{"type":"p","style":"Normal","text":"Per Striker e Crusher, Forza in Prestigio rende disponibili la scala di distruzione ambientale e Proiezione Colossale. Sono potenziamenti passivi dell'Attributo, con costo aggiuntivo di 0 ST e senza una scelta di Talento. La distruzione riguarda un impatto basato su Forza o una capacità che utilizza espressamente la sua scala, come il Talento Onda Titanica dello Striker e Onda Sismica del Crusher. La Proiezione Colossale richiede una Tecnica offensiva in mischia del proprio Ruolo contenente l’effetto Proiezione del Costruttore. Tutti i costi della Tecnica e degli effetti utilizzati restano dovuti."},{"type":"p","style":"Normal","text":"Questo serve solo a distinguerla dal Talento Proiezione dello Striker e dalle altre capacità che producono una spinta propria.","aggiunta":true},{"type":"p","style":"Heading 3","text":"Scale del Prestigio di Forza"},{"type":"table","rows":[["Prestigio di Forza","Dado di Forza","Proiezione massima","Raggio massimo di distruzione"],["I","d20+d4","10 m","5 m"],["II","d20+d6","15 m","10 m"],["III","d20+d8","20 m","30 m"],["IV","d20+d10","30 m","100 m"],["V","d20+d12","50 m","300 m"],["Saikyō","d20+d20","100 m","1.000 m"]]},{"type":"p","style":"Normal","text":"I valori sono massimi. Puoi scegliere una distanza o un raggio inferiore. Il raggio di distruzione si misura dal punto d’impatto: un raggio di 100 m corrisponde a un’area di 200 m di diametro. A Saikyō, il raggio di 1.000 m corrisponde a un diametro di 2.000 m."},{"type":"p","style":"Normal","text":"Non devi tirare Forza per determinare quanti metri raggiungi: usi la riga corrispondente al suo dado attuale. Il tiro di Forza serve quando una regola richiede una prova o, nel caso di Schianto, per determinare i danni."},{"type":"p","style":"Normal","text":"Se Forza non ha ancora raggiunto il Prestigio, rimangono le distanze e le dimensioni previste dagli effetti ordinari. In particolare, l’effetto Proiezione di una Tecnica conserva i suoi 3 m."},{"type":"p","style":"Heading 3","text":"Distruzione dello scenario"},{"type":"p","style":"Normal","text":"La scala di distruzione esprime l’estensione massima delle conseguenze ambientali di un colpo di Forza: pavimentazione spezzata, terreno scavato, porte divelte, coperture infrante e parti di strutture danneggiate. Il punto d’impatto è il centro dell’area."},{"type":"p","style":"Normal","text":"Il raggio indica quanto lontano può estendersi la devastazione. La distruzione effettiva dipende dal colpo, dal materiale, dalla resistenza dell’ostacolo e dai danni inflitti. Un muro resistente può restare in piedi anche se rientra nell’area massima. La scala non rende ogni oggetto dell’area automaticamente distrutto."},{"type":"p","style":"Normal","text":"Per le strutture dotate di Punti Struttura, abbreviati PS, sottrai i danni effettivamente subiti e applica le conseguenze previste quando cedono. Per gli elementi senza PS, il GM determina rotture e cedimenti coerenti con il danno e con il materiale. Quando un impatto si propaga nell’area, il danno diminuisce con la distanza secondo le fasce seguenti."},{"type":"p","style":"Normal","text":"Per Striker e Crusher la scala delimita le conseguenze sullo scenario; il colpo o l’effetto utilizzato stabilisce quali bersagli ricevono danni numerici. Per infliggere il danno del colpo alle creature di un’area serve il Talento Onda Titanica dello Striker, Onda Sismica del Crusher oppure una Tecnica che lo preveda. La sola Forza di Prestigio non assegna danni a tutte le creature entro il raggio."},{"type":"p","style":"Normal","text":"Anche uno Schianto può produrre crepe, detriti e rotture compatibili con questa scala. Il suo danno resta quello stabilito da Proiezione Colossale e viene applicato soltanto ai destinatari indicati nella regola del primo urto."},{"type":"p","style":"Heading 4","text":"Condizioni di attivazione della distruzione ambientale"},{"type":"p","style":"Normal","text":"Tipo: potenziamento passivo dell’Attributo Forza. Ruoli: Striker e Crusher. Requisito: Forza almeno d20+d4 e un impatto compatibile sullo scenario. Costo aggiuntivo: 0 ST. Azione aggiuntiva: nessuna."},{"type":"p","style":"Normal","text":"Puoi utilizzare la scala quando metti a segno un attacco basato su Forza e l’impatto si scarica effettivamente sul terreno, su un oggetto o su una struttura. Può essere un attacco base o una Tecnica offensiva del tuo Ruolo: uno Striker può colpire il suolo con un pugno; un Crusher può abbattere il martello sul pavimento o contro un muro. Per il Crusher l’attacco deve utilizzare un’arma contundente compatibile."},{"type":"p","style":"Normal","text":"Un colpo contro una creatura può coinvolgere anche lo scenario se l’impatto si trasmette a una superficie o a una struttura. Occorre individuare il contatto che produce la devastazione: colpire un avversario addossato a un muro, scaricare il colpo sul terreno sotto di lui oppure farlo urtare contro una superficie con gli effetti previsti. Il semplice fatto di colpire una creatura non danneggia automaticamente tutto lo scenario circostante."},{"type":"p","style":"Normal","text":"La scala esprime la capacità di estendere un impatto effettivo. Un colpo mancato o evitato non produce automaticamente un’area di danni. Se durante la risoluzione si verifica comunque un urto contro lo scenario, quell’urto deve essere riconosciuto e risolto con i propri danni; non si presume che sia avvenuto soltanto perché Forza è in Prestigio."},{"type":"p","style":"Normal","text":"Per la sola distruzione ambientale non occorre acquisire un Talento di Prestigio della Skill e non servono Proiezione o Schianto nella Tecnica. Questi effetti diventano necessari quando vuoi scagliare una creatura e infliggere il danno da collisione descritto nelle sezioni successive. Una normale prova di Forza per sollevare, trascinare o spingere un oggetto non infligge automaticamente il danno di un attacco."},{"type":"p","style":"Heading 4","text":"Procedura per lo scenario"},{"type":"p","style":"Normal","text":"Prima del tiro dichiara il punto che vuoi colpire e, se vuoi propagare la devastazione, l’estensione scelta entro il raggio massimo della tua Forza. Risolvi l’attacco con la sua normale portata, le azioni necessarie e gli eventuali costi della Tecnica. Una superficie senza difese non richiede una prova aggiuntiva per attivare il potenziamento; gli eventuali tiri necessari a raggiungerla o colpirla seguono le regole ordinarie."},{"type":"p","style":"Normal","text":"Quando l’impatto avviene, usa il danno del colpo come D e applica alle strutture raggiunte la fascia della loro distanza dal punto d’impatto. Per uno Schianto usa invece soltanto il suo tiro di Forza, rispettando il limite dei destinatari del primo urto. Non effettuare un ulteriore tiro di Forza per determinare il raggio o per aggiungere danni ambientali non previsti."},{"type":"p","style":"Normal","text":"Per le strutture con PS, sottrai il danno effettivo dopo le riduzioni pertinenti. Demolitore del Crusher e Pugni che Rompono dello Striker, se posseduti, conservano i propri benefici contro gli oggetti compatibili; le fasce di attenuazione continuano ad applicarsi. Per gli elementi senza PS il GM determina le conseguenze coerenti con il danno e il materiale."},{"type":"p","style":"Normal","text":"L’impatto deve poter raggiungere gli elementi coinvolti: un ostacolo che resiste può fermarne la propagazione. Il raggio massimo non garantisce che ogni struttura nell’area si rompa. Puoi scegliere un’estensione inferiore e una capacità particolare può delimitare diversamente la zona, come il cono di Onda Sismica."},{"type":"p","style":"Heading 4","text":"Danni alle creature e attivazione dei Talenti"},{"type":"p","style":"Normal","text":"La sola distruzione ambientale applica i danni propagati allo scenario. Le creature ricevono il danno diretto dell’attacco soltanto se sono bersagli della capacità usata. Crolli, cadute e altri pericoli prodotti dalla rottura dello scenario possono comunque ferirle secondo le normali regole dell’ambiente; non equivalgono a una copia automatica del danno del pugno o del martello."},{"type":"p","style":"Normal","text":"Lo Striker che possiede il Talento Onda Titanica può, dopo un proprio colpo riuscito nel suo turno, spendere l’Azione Bonus e 2 ST per investire anche le altre creature nell’area radiale scelta. Il Crusher che possiede Onda Sismica può, dopo un colpo contundente di Forza con un contatto valido sullo scenario nel suo turno, spendere l’Azione Bonus e 3 ST per attaccare le creature appoggiate alla superficie nel cono scelto. Entrambi utilizzano la stessa scala di Forza, con i limiti e le difese descritti nei rispettivi Talenti."},{"type":"p","style":"Normal","text":"Un Talento o una Tecnica che concede un attacco ad area stabilisce anche quali creature colpisci. La scala di Forza non allarga automaticamente l’area di qualsiasi Tecnica: una mossa deve richiamare espressamente questa scala per utilizzarla contro le creature. Le sue azioni, gli effetti, gli slot e i costi restano necessari."},{"type":"p","style":"Normal","text":"Le strutture raggiunte da uno stesso impatto ricevono una sola applicazione del danno della propria fascia. La scala passiva e il Talento che propaga quel colpo non generano due copie di danno sullo stesso oggetto o sulla stessa creatura."},{"type":"p","style":"Normal","text":"Esempio dello Striker: con Forza d20+d10 colpisci il terreno e ottieni 40 danni. Il raggio massimo è 100 m. Una pavimentazione a 40 m può ricevere 20 danni ambientali, secondo resistenza e PS; una guardia a quella distanza non riceve automaticamente quei 20 danni. Se dopo il colpo attivi Onda Titanica pagando l’Azione Bonus e 2 ST, la guardia raggiunta dall’onda può difendersi: se viene colpita, riceve anche i 20 danni previsti dalla sua fascia. La pavimentazione non riceve altri 20 danni per la seconda descrizione dello stesso impatto."},{"type":"p","style":"Heading 4","text":"Forma Area e propagazione dell’impatto","aggiunta":true},{"type":"p","style":"Normal","text":"Una Tecnica con Forma Area e la propagazione di un impatto sono meccaniche differenti. Swordsman e Crusher hanno soltanto Area Ravvicinata (d8, 2 ST), centrata sul personaggio con raggio pari alla Portata effettiva dell’arma. Striker e Sniper non possiedono una Forma Area ordinaria di Stile.","aggiunta":true},{"type":"p","style":"Normal","text":"Aree diverse richiedono una Fonte speciale che le conceda espressamente. Una Tecnica Area mantiene la propria sagoma, effetti, slot e costi.","aggiunta":true},{"type":"p","style":"Normal","text":"La distruzione ambientale del Prestigio di Forza nasce da un singolo impatto fisico identificabile sul terreno, un oggetto o una struttura. Un’Area non genera un punto d’impatto per ogni creatura e non moltiplica la scala di distruzione; si risolve un solo punto valido. La scala conserva il proprio raggio e le proprie regole.","aggiunta":true},{"type":"p","style":"Heading 4","text":"Danni in base alla distanza"},{"type":"p","style":"Normal","text":"Questa regola si applica ai danni propagati dal Talento Onda Titanica dello Striker, da Onda Sismica del Crusher e alla distruzione ambientale nell’area. Chiama D il danno complessivo del colpo che genera l’impatto, prima delle riduzioni del bersaglio iniziale. Comprende Potenza del Titano dello Striker, il tiro aggiuntivo di Forza di Maglio Inarrestabile del Crusher e gli altri bonus applicabili al colpo; esclude un eventuale Schianto successivo. Chiama R il raggio massimo stabilito dal Prestigio di Forza."},{"type":"p","style":"Normal","text":"Misura la distanza di ciascuna creatura o struttura dal punto d’impatto e applica la fascia corrispondente."},{"type":"table","rows":[["Distanza dal punto d’impatto","Danno propagato"],["Fino a un quarto di R compreso","D"],["Oltre un quarto e fino a metà di R compresa","Metà di D"],["Oltre metà e fino a tre quarti di R compresi","Un quarto di D"],["Oltre tre quarti e fino a R compreso","Un ottavo di D"]]},{"type":"p","style":"Normal","text":"Arrotonda ogni frazione per difetto, poi applica le riduzioni proprie del destinatario. Un risultato pari a zero non infligge danni. Il bersaglio del colpo iniziale riceve quel colpo una sola volta e non riceve anche una seconda copia del danno propagato."},{"type":"p","style":"Normal","text":"Le soglie dipendono dal raggio massimo della tua Forza. Se scegli un’area più piccola, limiti quali bersagli vengono raggiunti e mantieni le stesse soglie di danno. Oltre il raggio scelto, il colpo non si propaga."},{"type":"table","rows":[["Dado di Forza","D fino a","Metà di D fino a","Un quarto di D fino a","Un ottavo di D fino a"],["d20+d4","1,25 m","2,5 m","3,75 m","5 m"],["d20+d6","2,5 m","5 m","7,5 m","10 m"],["d20+d8","7,5 m","15 m","22,5 m","30 m"],["d20+d10","25 m","50 m","75 m","100 m"],["d20+d12","75 m","150 m","225 m","300 m"],["d20+d20","250 m","500 m","750 m","1.000 m"]]},{"type":"p","style":"Normal","text":"Le colonne indicano il limite superiore di ciascuna fascia; ogni fascia successiva comincia oltre il limite della precedente. La scala dei danni non autorizza da sola un attacco ad area contro le creature: occorre sempre una capacità che le investa."},{"type":"p","style":"Normal","text":"Esempio a Saikyō: un impatto da 40 danni propaga 40 danni entro 250 m, 20 oltre 250 e fino a 500 m, 10 oltre 500 e fino a 750 m, e 5 oltre 750 e fino a 1.000 m. Con la sola scala di distruzione questi valori riguardano le strutture raggiunte. Le creature li ricevono soltanto se una capacità le investe direttamente, come Onda Titanica oppure Onda Sismica, e possono applicare le proprie difese. Ogni destinatario applica poi le riduzioni pertinenti. La distruzione più intensa resta concentrata vicino al punto d’impatto."},{"type":"p","style":"Heading 3","text":"Proiezione Colossale"},{"type":"p","style":"Normal","text":"Tipo: potenziamento passivo del Prestigio di Forza. Ruoli: Striker e Crusher. Costo aggiuntivo: 0 ST. Requisito di impiego: una Tecnica offensiva in mischia del proprio Ruolo con l’effetto Proiezione. Per i danni da urto: la stessa Tecnica deve contenere anche Schianto."},{"type":"p","style":"Normal","text":"Quando una Tecnica compatibile colpisce e applica Proiezione, puoi sostituire i 3 m previsti dall’effetto ordinario con la distanza massima del tuo Prestigio di Forza. Dichiara la direzione del lancio e la distanza scelta, fino al massimo consentito dalla scala."},{"type":"p","style":"Normal","text":"Con Forza d20+d8 puoi scagliare il bersaglio fino a 20 m; con Forza d20+d12 fino a 50 m. Puoi scegliere un lancio più corto. La massa e la stazza del bersaglio devono essere compatibili con ciò che la tua Forza permette di scagliare: la scala in metri non concede da sola la capacità di sollevare qualsiasi peso."},{"type":"p","style":"Normal","text":"La distanza di lancio si misura dalla posizione del bersaglio colpito. È lo spostamento provocato dopo il colpo e non la portata dell’attacco: devi prima raggiungere e colpire il bersaglio con la normale portata della Tecnica."},{"type":"p","style":"Normal","text":"Questo impiego modifica l’effetto Proiezione contenuto nella Tecnica e non richiede che il bersaglio sia già Trattenuto. Il Talento ordinario chiamato Proiezione, che lancia un nemico già trattenuto fino a 5 m, mantiene le sue condizioni quando viene usato separatamente. Possederlo non sostituisce l’effetto che deve essere presente nella Tecnica."},{"type":"p","style":"Normal","text":"Proiezione Colossale non concede un lancio su qualunque attacco base e non aggiunge gratuitamente gli effetti necessari alla Tecnica. Proiezione occupa il proprio slot Effetto e conserva il costo ordinario di 1 ST. Schianto, se presente, occupa un altro slot e conserva il costo ordinario di 2 ST. Il potenziamento del Prestigio ha costo aggiuntivo 0 ST, ma non rende gratuita la Tecnica, non aumenta gli slot e non elimina gli altri requisiti."},{"type":"p","style":"Normal","text":"Gli ostacoli possono interrompere il lancio prima della distanza dichiarata. Se il primo ostacolo cede, la traiettoria può proseguire entro la distanza residua; se resiste, il bersaglio si arresta contro di esso. Eventuali urti ulteriori non ripetono il danno aggiuntivo di questa capacità."},{"type":"p","style":"Heading 3","text":"Schianto con Proiezione Colossale"},{"type":"p","style":"Normal","text":"Quando la Tecnica contiene sia Proiezione sia Schianto, il primo urto del bersaglio scagliato contro una creatura o una superficie attiva il danno da Schianto. L’atterraggio sul terreno può costituire questo primo urto."},{"type":"p","style":"Normal","text":"Danno da Schianto = un tiro completo di Forza."},{"type":"p","style":"Normal","text":"Tira una sola volta il dado di Forza, compreso il dado di Prestigio, e somma i risultati. Con Forza d20+d8 il danno da Schianto è quindi il risultato di d20+d8. Questo tiro sostituisce il normale +1d8 di Schianto: non si sommano entrambi."},{"type":"p","style":"Normal","text":"Applica lo stesso risultato una volta a ciascuno dei seguenti destinatari:"},{"type":"p","style":"List Bullet","text":"Il bersaglio scagliato, come danno aggiuntivo rispetto al danno iniziale della Tecnica."},{"type":"p","style":"List Bullet","text":"La prima creatura o struttura effettivamente urtata, come danno dell’impatto."},{"type":"p","style":"Normal","text":"Il bersaglio scagliato ha già subito l’attacco che lo proietta; al primo urto applica le riduzioni pertinenti al danno da Schianto. Una seconda creatura coinvolta può difendersi normalmente contro il risultato per colpire della Tecnica originaria: se evita l’urto, non riceve il danno e non conta come la prima collisione effettiva. Se viene colpita, riceve soltanto il tiro di Forza, con le proprie normali riduzioni."},{"type":"p","style":"Normal","text":"Un ostacolo dotato di PS perde Punti Struttura pari al danno da Schianto effettivamente ricevuto. Il danno iniziale della Tecnica non viene copiato sull’ostacolo o su una seconda creatura."},{"type":"p","style":"Normal","text":"Il tiro di Schianto non riceve nuovamente Potenza del Titano, il Dado Danno della Tecnica o i bonus di danno dell’Haki. La sua formula resta un solo tiro completo di Forza. La lunghezza del lancio e il numero di oggetti lungo la traiettoria non aggiungono moltiplicatori."},{"type":"p","style":"Normal","text":"Puoi applicare questo danno da Schianto una sola volta per uso della Tecnica, al primo urto effettivo. Attraversare o incontrare altri ostacoli non genera nuove copie del tiro. Eventuali altri pericoli ambientali distinti restano regolati dalle loro regole."},{"type":"p","style":"Heading 4","text":"Proiezione senza Schianto"},{"type":"p","style":"Normal","text":"Una Tecnica con Proiezione ma priva di Schianto infligge il proprio normale danno e può scagliare il bersaglio alla distanza consentita da Forza. Proiezione Colossale non le assegna danni aggiuntivi da urto, né contro il bersaglio né contro ciò che incontra."},{"type":"p","style":"Heading 4","text":"Esempio completo di collisione"},{"type":"p","style":"Normal","text":"Uno Striker possiede Forza d20+d8 e usa una Tecnica con Proiezione e Schianto. Il suo lancio massimo è di 20 m. La Tecnica colpisce e infligge 30 danni iniziali, già comprensivi degli eventuali bonus al colpo."},{"type":"p","style":"Normal","text":"Lo Striker sceglie di scagliare il nemico verso un muro a 12 m dalla posizione di partenza del bersaglio. Il nemico urta il muro. Per Schianto, lo Striker tira d20+d8 e ottiene un totale di 18."},{"type":"p","style":"List Bullet","text":"Il nemico riceve 30 danni dalla Tecnica e 18 da Schianto, per un totale di 48 prima delle eventuali riduzioni."},{"type":"p","style":"List Bullet","text":"Il muro riceve 18 danni strutturali. Se possiede 40 PS e nessuna riduzione pertinente, scende a 22 PS."},{"type":"p","style":"Normal","text":"Il muro resiste, quindi il lancio termina a 12 m. Non riceve i 30 danni iniziali e non si aggiunge il normale +1d8 di Schianto. Se invece cedesse e la traiettoria proseguisse, il danno da Schianto sarebbe comunque già stato applicato una volta."},{"type":"p","style":"Normal","text":"La stessa risoluzione si applica a un Crusher che utilizza una Tecnica compatibile con Proiezione e Schianto. La proiezione potenziata dipende da Forza, indipendentemente dalla Skill che ha sbloccato eventuali Talenti del Ruolo."}]},"Tecnica":{"source":"combattenti","start":85,"end":120,"anchor":"combattenti-prestigio-di-tecnica","blocks":[{"type":"p","style":"Normal","text":"Per Striker e Swordsman, l'Attributo Tecnica in Prestigio concede automaticamente Spostamento Fulmineo e le possibilità di Agilità Sovrumana previste dalla sua soglia. Questi potenziamenti non occupano scelte di Talento e non richiedono che la Skill di Ruolo abbia già raggiunto il Prestigio. Sniper e Crusher non ricevono questo pacchetto di mobilità."},{"type":"p","style":"Normal","text":"Per Striker e Swordsman, questo modulo ammette Scatto e Balzo nelle Tecniche compatibili del proprio Stile, rispettandone Grado, Forma, slot e costi. Sniper e Crusher non ricevono questo pacchetto di mobilità. Il valore di mobilità si legge sempre dall’Attributo Tecnica del personaggio, anche quando il colpo utilizza un diverso Attributo consentito. Inseguire è rimosso dal Costruttore e non fa parte della scala di Prestigio."},{"type":"p","style":"Heading 3","text":"Scala del Prestigio di Tecnica"},{"type":"table","rows":[["Attributo Tecnica","Spostamento speciale massimo per turno","Altezza massima di un Balzo"],["d20+d4","10 m","5 m"],["d20+d6","15 m","10 m"],["d20+d8","20 m","15 m"],["d20+d10","30 m","20 m"],["d20+d12","100 m","50 m"],["d20+d20 Saikyō","1.000 m","200 m"]]},{"type":"p","style":"Normal","text":"I valori sono massimi e puoi scegliere distanze inferiori. La riga si legge dal grado attuale dell’Attributo Tecnica, senza tirare per determinare i metri. I potenziamenti dell’Attributo si applicano quando utilizzi gli effetti compatibili nella Tecnica."},{"type":"p","style":"Normal","text":"Spostamento Fulmineo utilizza la scala esclusivamente con Scatto. Agilità Sovrumana utilizza la scala con Balzo. I due impieghi condividono un unico budget di spostamento speciale: combinarli o possedere più Stili compatibili non raddoppia i metri disponibili."},{"type":"p","style":"Normal","text":"Il budget si rinnova all’inizio del tuo turno e rimane disponibile fino all’inizio del successivo. Gli usi fuori dal tuo turno, quando consentiti dalle regole della capacità utilizzata, consumano il budget ancora disponibile. Ogni spostamento sottrae i metri effettivamente percorsi; salita e cambi di direzione fanno parte del percorso."},{"type":"p","style":"Normal","text":"L’altezza del Balzo limita quanto puoi salire rispetto al punto di partenza di quel singolo salto. Non concede metri aggiuntivi: un Balzo che sale di 20 m consuma almeno 20 m del budget disponibile."},{"type":"p","style":"Normal","text":"Il Movimento ordinario rimane distinto e segue le proprie regole; non moltiplica automaticamente il budget di questa scala. Se l’Attributo Tecnica non è ancora in Prestigio, Scatto e Balzo conservano le distanze ordinarie."},{"type":"p","style":"Normal","text":"La crescita delle prime quattro soglie rimane contenuta. Il salto di scala arriva a d20+d12 e soprattutto a Saikyō: lo spostamento massimo di 1.000 m rappresenta una manovra dei maestri più forti nel proprio campo."},{"type":"p","style":"Heading 3","text":"Spostamento Fulmineo"},{"type":"p","style":"Normal","text":"Tipo: potenziamento passivo del Prestigio di Tecnica. Ruoli: Striker e Swordsman. Costo aggiuntivo: 0 ST. Requisito di impiego: una Tecnica del proprio Stile compatibile con Scatto. Limite: il budget condiviso di spostamento speciale."},{"type":"p","style":"Normal","text":"Quando utilizzi Scatto, puoi sostituire la distanza ordinaria dell’effetto con una distanza entro il budget disponibile della scala. Puoi distribuire i metri fra più Tecniche nello stesso turno, pagando ogni volta i costi della mossa utilizzata."},{"type":"p","style":"Normal","text":"Scatto conserva la possibilità di spostarti prima o dopo il colpo. Gli attacchi richiedono i normali tiri e la normale portata dopo che hai raggiunto la posizione utile."},{"type":"p","style":"Normal","text":"Durante questi spostamenti non provochi Reazioni dovute all’allontanamento dalla portata di un nemico. Le altre Reazioni seguono normalmente i propri eventi di attivazione. Il percorso deve essere fisicamente percorribile; Agilità Sovrumana amplia gli appoggi che puoi utilizzare."},{"type":"p","style":"Normal","text":"Scatto occupa il proprio slot Effetto e conserva il costo ordinario di 1 ST. Balzo occupa il proprio slot e conserva il costo ordinario di 1 ST. Le Tecniche rispettano i requisiti di Grado e le compatibilità della Forma; il potenziamento non assegna effetti o slot gratuiti."},{"type":"p","style":"Normal","text":"Esempio: con Attributo Tecnica d20+d12 hai 100 m speciali disponibili. Usi Scatto per percorrerne 40 e raggiungere un nemico, pagando il costo della Tecnica. Un uso successivo può consumare al massimo i 60 m rimasti. Cinque attacchi di Raffica non trasformano il budget in cinque spostamenti da 100 m."},{"type":"p","style":"Heading 3","text":"Agilità Sovrumana"},{"type":"p","style":"Normal","text":"Tipo: potenziamento passivo del Prestigio di Tecnica. Ruoli: Striker e Swordsman. Costo aggiuntivo: 0 ST. Requisito per i balzi potenziati: una Tecnica del proprio Ruolo compatibile con Balzo. Costo ordinario di Balzo: 1 ST e il relativo slot Effetto."},{"type":"p","style":"Normal","text":"Quando utilizzi Balzo, puoi sostituire la distanza ordinaria con una distanza entro il budget disponibile, rispettando anche l’altezza massima del singolo salto. Il grado dell’Attributo Tecnica determina inoltre le seguenti possibilità."},{"type":"p","style":"Heading 4","text":"Appoggi impossibili"},{"type":"p","style":"Normal","text":"Con Attributo Tecnica d20+d4 o superiore puoi percorrere pareti, alberi delle navi, corde e superfici fragili senza interrompere il movimento a causa della precarietà dell’appoggio. Il percorso deve offrire punti effettivamente utilizzabili e devi concluderlo su un appoggio capace di sostenerti."},{"type":"p","style":"Normal","text":"Questa capacità si applica al Movimento ordinario e agli spostamenti speciali consentiti. Ciascuno consuma i metri della propria risorsa. Le pareti percorribili e i supporti precari non impongono una prova soltanto per il fatto di essere verticali o instabili; eventuali minacce e ostacoli ulteriori si risolvono normalmente."},{"type":"p","style":"Heading 4","text":"Balzi nell’aria"},{"type":"p","style":"Normal","text":"Da Attributo Tecnica d20+d8 puoi prendere impulso nell’aria con Balzo. Puoi cambiare direzione mentre sei sospeso o durante una caduta, raggiungere un bersaglio sopra di te oppure passare verso un nuovo appoggio senza dover prima toccare terra."},{"type":"p","style":"Normal","text":"Ogni uso paga il costo della Tecnica e consuma i metri effettivamente percorsi. Il limite di altezza vale per ciascun Balzo; una sequenza di balzi rimane limitata dal budget complessivo."},{"type":"p","style":"Normal","text":"Se termini la manovra senza un appoggio o una capacità che ti sostenga, riprendi a cadere. L’utilizzo della Tecnica segue la normale economia delle azioni: Balzo può essere impiegato fuori dal tuo turno soltanto quando una capacità lo consente espressamente. Questo passivo non assegna Reazioni aggiuntive."},{"type":"p","style":"Heading 4","text":"Sospensione aerea"},{"type":"p","style":"Normal","text":"Da Attributo Tecnica d20+d12, dopo un Balzo aereo puoi mantenerti sospeso fino all’inizio del tuo prossimo turno. Il mantenimento fino a quel momento è compreso nell’uso di Balzo; non richiede un’altra Azione Bonus o un costo separato."},{"type":"p","style":"Normal","text":"All’inizio del turno successivo puoi eseguire una nuova Tecnica con Balzo prima di risolvere la caduta. La Tecnica richiede la propria azione e il proprio costo ordinari; un nuovo Balzo aereo rinnova la sospensione. Se non effettui una nuova manovra e non raggiungi un appoggio, riprendi a cadere."},{"type":"p","style":"Normal","text":"Esempio: sei già in aria e possiedi Attributo Tecnica d20+d12. Prendi impulso con un Balzo aereo e sali fino a 50 m, usando parte dei 100 m speciali disponibili. Dopo la manovra rimani sospeso fino al prossimo turno. Nel turno successivo il budget si rinnova e puoi usare una nuova Tecnica con Balzo per continuare il combattimento in aria."},{"type":"p","style":"Heading 3","text":"Esempio di avvicinamento a Saikyō"},{"type":"p","style":"Normal","text":"Uno Swordsman possiede Attributo Tecnica d20+d20. Ha 1.000 m speciali disponibili e può usare una Tecnica con Scatto o Balzo per raggiungere una nave distante, purché l'intero percorso rientri nel budget e la traiettoria sia consentita. Per un attraversamento in aria utilizza Balzo e le possibilità di Agilità Sovrumana; Scatto da solo richiede un percorso fisicamente percorribile."},{"type":"p","style":"Normal","text":"Se percorre 800 m, rimangono 200 m speciali fino al rinnovo del budget. Il colpo si risolve soltanto quando il bersaglio è nella normale portata della lama. Lo Swordsman paga la Tecnica, compreso 1 ST per Scatto oppure 1 ST per Balzo. Se la mossa contiene entrambi gli effetti paga entrambi, rispettando i limiti ordinari della costruzione. Il movimento non assegna un attacco aggiuntivo o un colpo automatico."}]},"Astuzia":{"source":"combattenti","start":127,"end":146,"anchor":"combattenti-prestigio-di-astuzia","blocks":[{"type":"p","style":"Normal","text":"Per lo Sniper, l'Attributo Astuzia in Prestigio concede automaticamente Calcolo Balistico Sovrumano e la scala di Geometria del Tiro. Questi potenziamenti non occupano scelte di Talento e non richiedono che Osservazione abbia già raggiunto il Prestigio. Si applicano attraverso armi a distanza o da lancio compatibili con lo Stile Sniper. Striker, Swordsman, Crusher e gli altri Ruoli non ricevono questo pacchetto in questo modulo."},{"type":"p","style":"Normal","text":"Astuzia determina la gittata garantita e il numero di deviazioni disponibili; il tiro per colpire mantiene l'Attributo previsto dall'arma o dalla Tecnica. L'Attributo del colpo rimane quello registrato nella sua scheda e non si cambia liberamente per utilizzare un dado più alto."},{"type":"p","style":"Heading 3","text":"Scala del Prestigio di Astuzia"},{"type":"table","rows":[["Attributo Astuzia","Gittata utile minima","Deviazioni con Colpo Impossibile"],["d20+d4","100 m","1"],["d20+d6","150 m","1"],["d20+d8","200 m","2"],["d20+d10","300 m","2"],["d20+d12","1.000 m","3"],["d20+d20 Saikyō","5.000 m","5"]]},{"type":"p","style":"Normal","text":"Leggi la riga dal grado attuale dell'Attributo Astuzia, senza tirare per determinare i metri o le deviazioni. La crescita resta contenuta nelle prime quattro soglie; l'aumento maggiore arriva a d20+d12 e soprattutto a Saikyō. Se Astuzia non è ancora in Prestigio, restano le distanze dell'arma, i Talenti ordinari e le normali possibilità di Colpo Impossibile."},{"type":"p","style":"Normal","text":"La gittata utile minima è una portata garantita dal potenziamento, non un limite che riduce le capacità precedenti. Se l'arma o Tiro Lungo permettono già di colpire oltre, mantieni quella possibilità. Le deviazioni sono invece il massimo utilizzabile per il percorso di un singolo attacco con Colpo Impossibile e puoi impiegarne meno."},{"type":"p","style":"Heading 3","text":"Calcolo Balistico Sovrumano"},{"type":"p","style":"Normal","text":"Tipo: potenziamento passivo del Prestigio di Astuzia. Ruolo: Sniper. Costo aggiuntivo: 0 ST. Applicazione: armi a distanza o da lancio compatibili con lo Stile."},{"type":"p","style":"Normal","text":"Sai compensare la distanza, il vento e il movimento del bersaglio per eseguire un tiro preciso. La gittata utile della tua arma diventa almeno quella della scala di Astuzia, conservando eventuali portate superiori già possedute. Entro questa distanza infliggi il danno normale, senza penalità dovute soltanto alla lontananza."},{"type":"p","style":"Normal","text":"Il bersaglio deve essere individuato oppure devi conoscerne una posizione sufficientemente precisa per il tiro. La scala della gittata non individua automaticamente creature nascoste: per localizzarle utilizzi normalmente Osservazione, strumenti o altre capacità appropriate. Ostacoli, occultamento, difese e condizioni che impediscono materialmente l'attacco continuano a essere risolti secondo le rispettive regole."},{"type":"p","style":"Normal","text":"Il potenziamento riguarda la gittata utile dell'arma. Una Tecnica mantiene i requisiti e i limiti specifici della propria Forma e dei propri Effetti. Munizioni, ricarica, azioni e costi ordinari restano necessari."},{"type":"p","style":"Normal","text":"Esempio: con Astuzia d20+d12, il tuo fucile compatibile può colpire almeno fino a 1.000 m. Se riesci a individuare una sentinella a 800 m e il tiro dispone di un percorso valido, effettui il normale attacco e infliggi il danno ordinario. Se un'altra capacità ti permette già di tirare oltre 1.000 m, conservi quella possibilità."},{"type":"p","style":"Heading 3","text":"Geometria del Tiro"},{"type":"p","style":"Normal","text":"Tipo: potenziamento passivo del Prestigio di Astuzia. Ruolo: Sniper. Costo aggiuntivo: 0 ST. Requisito di impiego: possedere e utilizzare Colpo Impossibile, che conserva il costo di 2 ST."},{"type":"p","style":"Normal","text":"Quando utilizzi Colpo Impossibile, puoi costruire un percorso che comprende fino al numero di deviazioni indicato dalla tua Astuzia. Le deviazioni possono essere rimbalzi su superfici o cambi di direzione consentiti dal percorso. Il tiro può anche passare attraverso aperture e feritoie: un passaggio rettilineo senza cambio di direzione non aggiunge una deviazione."},{"type":"p","style":"Normal","text":"Ogni tratto deve offrire un percorso utilizzabile dal proiettile e una superficie adatta quando serve un rimbalzo. Una deviazione non permette di attraversare una parete solida. La traiettoria deve essere definita prima di tirare e il percorso complessivo deve rientrare nella gittata consentita all'attacco."},{"type":"p","style":"Normal","text":"Colpo Impossibile conserva le proprie azioni e il costo di 2 ST, oltre agli eventuali costi della Tecnica. Geometria del Tiro modifica il percorso di un attacco e non concede nuovi bersagli. Per colpire più nemici occorrono Rimbalzo, Catena o un'altra capacità appropriata, con i suoi slot, costi e limiti."},{"type":"p","style":"Normal","text":"Esempio a Saikyō: conosci la posizione di un avversario su una nave distante 4.000 m. Usando Colpo Impossibile puoi progettare un tiro che attraversa un'apertura e utilizza fino a cinque deviazioni su superfici effettivamente disponibili, rispettando i 5.000 m complessivi della tua gittata utile minima. Paghi 2 ST e risolvi un normale attacco contro quel bersaglio."}]},"Lama":{"source":"combattenti","start":120,"end":127,"anchor":"combattenti-scale-di-forza-e-tecnica-per-lo-swordsman","blocks":[{"type":"p","style":"Normal","text":"Fendente Sovrano e Taglio Colossale utilizzano la scala dell'Attributo previsto dal colpo, Forza oppure Tecnica. La loro acquisizione appartiene al Prestigio della Skill di Ruolo Atletica e il loro impiego richiede i Talenti descritti nella parte seconda. La scala non concede da sola queste capacità."},{"type":"p","style":"Heading 3","text":"Scala dei fendenti e dei tagli"},{"type":"table","rows":[["Attributo del colpo","Portata di Fendente Sovrano","Dimensione massima di Taglio Colossale"],["d20+d4","20 m","5 m"],["d20+d6","30 m","10 m"],["d20+d8","50 m","30 m"],["d20+d10","100 m","100 m"],["d20+d12","300 m","300 m"],["d20+d20 Saikyō","1.000 m","1.000 m"]]},{"type":"p","style":"Normal","text":"I valori sono massimi: puoi scegliere distanze e dimensioni inferiori. I metri dipendono dal dado attuale dell’Attributo, senza tirare per determinarli. Per usare una colonna devi possedere il Talento corrispondente."},{"type":"p","style":"Normal","text":"La portata misura la distanza fra te e il punto da colpire. La dimensione del taglio misura la lunghezza della sezione che vuoi recidere nell’elemento scelto. Non è un raggio di distruzione e non assegna danni a tutti gli elementi circostanti. Taglio Colossale richiede di raggiungere il punto scelto con la portata del colpo; Fendente Sovrano permette di colpirlo da lontano."},{"type":"p","style":"Normal","text":"Se l’Attributo non è ancora in Prestigio, Fendente Sovrano conserva i 10 m di Fendente d’Aria e applica comunque il danno pieno. Taglio Colossale conserva il proprio bonus strutturale, mentre la dimensione della recisione segue i limiti ordinari del colpo."}]},"Spirito":{"source":"haki","start":35,"end":57,"anchor":"haki-prestigio-di-spirito","blocks":[{"type":"p","style":"Heading 2","text":"Acquisizione dei tre potenziamenti"},{"type":"p","style":"Normal","text":"Il Prestigio di Spirito vale per tutti i Ruoli. Si sceglie un potenziamento tra Volontà Indomabile, Sintonia dei Colori e Riscossa della Volontà a Spirito d20+d4, un secondo a d20+d8 e il terzo a d20+d12. Ogni potenziamento può essere acquisito una sola volta."},{"type":"p","style":"Normal","text":"L’ordine è libero. Questo permette, per esempio, di acquisire subito Riscossa della Volontà e far crescere il suo recupero con Spirito. A Saikyō migliorano i potenziamenti già posseduti, senza aggiungerne altri."},{"type":"p","style":"Heading 2","text":"Volontà Indomabile"},{"type":"p","style":"Normal","text":"Tipo: passivo. Costo: nessuno. Attivazione: automatica nei tiri pertinenti."},{"type":"p","style":"Normal","text":"Quando una regola richiede un tiro di Spirito per resistere a paura, intimidazione o coercizione mentale, il d20 di Spirito vale automaticamente 20. Si tira normalmente il dado aggiuntivo di Prestigio e l’eventuale Skill applicabile."},{"type":"p","style":"Normal","text":"Con Spirito d20+d8, il contributo dell’Attributo diventa quindi 20+d8. A Spirito Saikyō, anche il secondo d20 vale 20: il contributo di Spirito è 40, prima dell’eventuale Skill o degli altri modificatori consentiti."},{"type":"p","style":"Normal","text":"Il risultato viene comunque confrontato con la difficoltà o il tiro contrapposto richiesto. Il potenziamento non garantisce il successo e non modifica i tiri per colpire o i danni."},{"type":"p","style":"Normal","text":"Volontà Indomabile si applica soltanto quando l’effetto prevede effettivamente una prova di Spirito. Non crea una nuova prova contro effetti automatici. In particolare, non permette da sola di annullare Pressione Imperiale."},{"type":"p","style":"Heading 2","text":"Sintonia dei Colori"},{"type":"p","style":"Normal","text":"Tipo: attivo. Attivazione: un’Azione Bonus. Costo: 1 PIP per ciascun Colore attivato."},{"type":"p","style":"Normal","text":"Con una sola Azione Bonus puoi attivare due Colori dell’Haki che possiedi. A Spirito Saikyō puoi attivarne tre. Ogni Colore paga il proprio PIP dalla propria riserva."},{"type":"p","style":"Normal","text":"Armamento e Osservazione, per esempio, si accendono insieme pagando 1 PIP di Armamento e 1 di Osservazione. A Saikyō puoi aggiungere il Re soltanto se il personaggio lo possiede e dispone del PIP necessario."},{"type":"p","style":"Normal","text":"Sintonia non riduce i costi, non conferisce nuovi Colori e non attiva insieme anche Armatura Totale, Anticipo, Rivestimento o altri effetti attivi. Ogni Colore mantiene inoltre i propri costi ordinari di mantenimento."},{"type":"p","style":"Heading 2","text":"Riscossa della Volontà"},{"type":"p","style":"Normal","text":"Tipo: attivo. Attivazione: un’Azione Bonus. Costo: 0 Stamina. Limite: una volta, poi serve un riposo breve o lungo per poterla usare di nuovo."},{"type":"p","style":"Normal","text":"Richiami la tua determinazione e recuperi un numero di PIP determinato dal dado completo di Spirito. Il recupero è un unico totale da distribuire liberamente fra Armamento, Osservazione e Re, limitatamente ai Colori che possiedi."},{"type":"table","rows":[["Dado di Spirito","PIP totali recuperabili"],["d20+d4","1"],["d20+d6","2"],["d20+d8","3"],["d20+d10","4"],["d20+d12","5"],["d20+d20","6"]]},{"type":"p","style":"Normal","text":"Nessuna riserva può superare il proprio massimo. I PIP che non trovano spazio vengono persi: non si conservano per dopo e non aumentano la capacità dei Colori."},{"type":"p","style":"Normal","text":"Puoi usare Riscossa anche con tutte le riserve a zero o con i Colori spenti. Il recupero non accende automaticamente alcun Colore e non ripristina gli usi di capacità limitate a una volta per combattimento."},{"type":"p","style":"Normal","text":"Esempio: con Spirito d20+d12 recuperi fino a 5 PIP complessivi. Puoi assegnarne 2 ad Armamento, 2 a Osservazione e 1 al Re, se in ciascuna riserva c’è spazio. Non recuperi 5 PIP per ogni Colore."}]}}};})(typeof window!=="undefined"?window:globalThis);
